-- 018_public_views_visibility: keep public projections readable while private projections stay invoker-based.

begin;

do $$
declare
  view_name text;
  view_names text[] := array[
    'public_activity_events',
    'public_coin_balances',
    'public_cup_matches',
    'public_cup_participants',
