-- ============================================================================
-- BEGIN 019_team_lock_api.sql
-- ============================================================================
-- PokeApp V2 backend-only atomic Team Lock mutation. No legacy writes.
begin;

create or replace function public.api_upsert_team_lock(
  p_season_id uuid,
  p_matchday_id uuid,
  p_trainer_id uuid,
  p_season_player_id uuid,
  p_save_file_id uuid,
  p_save_sha256 text,
  p_parsed_save_id uuid,
  p_parsed_payload jsonb,
  p_public_team_snapshot jsonb,
  p_private_team_snapshot jsonb
)
returns setof public.team_locks
language plpgsql
security invoker
set search_path = ''
as $$
declare
  trainer_row public.trainers%rowtype;
  season_row public.seasons%rowtype;
  matchday_row public.matchdays%rowtype;
  player_row public.season_players%rowtype;
  save_row public.save_files%rowtype;
  parsed_row public.parsed_saves%rowtype;
  lock_row public.team_locks%rowtype;
  locked_time timestamptz;
begin
  -- Hold eligibility/source rows stable until the lock and event commit together.
  select * into trainer_row from public.trainers where id = p_trainer_id for share;
  if not found or not trainer_row.globally_enabled then
    raise sqlstate 'PT403' using message = 'trainer_disabled';
  end if;
  select * into season_row from public.seasons where id = p_season_id for share;
  if not found then
    raise sqlstate 'PT404' using message = 'season_not_found';
  end if;
  if season_row.status <> 'active' then
    raise sqlstate 'PT409' using message = 'season_not_active';
  end if;
  select * into matchday_row from public.matchdays
    where id = p_matchday_id and season_id = p_season_id for share;
  if not found then
    raise sqlstate 'PT404' using message = 'matchday_not_found';
  end if;
  if matchday_row.status not in ('scheduled', 'open') or matchday_row.closed_at is not null then
    raise sqlstate 'PT409' using message = 'matchday_not_lockable';
  end if;
  select * into player_row from public.season_players
    where id = p_season_player_id and season_id = p_season_id and trainer_id = p_trainer_id for share;
  if not found then
    raise sqlstate 'PT404' using message = 'participation_not_found';
  end if;
  if player_row.status <> 'active' then
    raise sqlstate 'PT403' using message = 'participant_inactive';
  end if;
  select * into save_row from public.save_files
    where id = p_save_file_id and season_id = p_season_id and trainer_id = p_trainer_id for share;
  if not found then
    raise sqlstate 'PT404' using message = 'save_not_found';
  end if;
  if save_row.deleted_at is not null or save_row.parser_status <> 'parsed'
     or save_row.sha256 is distinct from p_save_sha256 then
    raise sqlstate 'PT409' using message = 'save_not_ready';
  end if;
  select * into parsed_row from public.parsed_saves
    where id = p_parsed_save_id and save_file_id = p_save_file_id
      and parser_version = save_row.parser_version for share;
  if not found then
    raise sqlstate 'PT409' using message = 'parsed_save_not_ready';
  end if;
  if parsed_row.status <> 'parsed' or parsed_row.schema_version <> 1
     or jsonb_typeof(parsed_row.payload) is distinct from 'object'
     or parsed_row.payload is distinct from p_parsed_payload then
    raise sqlstate 'PT409' using message = 'parsed_save_changed';
  end if;
  if jsonb_typeof(parsed_row.payload -> 'party') is distinct from 'array'
     or jsonb_typeof(p_public_team_snapshot) is distinct from 'array'
     or jsonb_typeof(p_private_team_snapshot) is distinct from 'array' then
    raise sqlstate 'PT409' using message = 'invalid_team_snapshot';
  end if;
  if jsonb_array_length(parsed_row.payload -> 'party') <> 6
     or jsonb_array_length(p_public_team_snapshot) <> 6
     or jsonb_array_length(p_private_team_snapshot) <> 6 then
    raise sqlstate 'PT409' using message = 'team_requires_six';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_public_team_snapshot || p_private_team_snapshot) as mon(value)
    where jsonb_typeof(value) is distinct from 'object'
       or jsonb_typeof(value -> 'species') is distinct from 'string'
       or length(btrim(value ->> 'species')) = 0
  ) then
    raise sqlstate 'PT409' using message = 'invalid_team_snapshot';
  end if;

  -- No authoritative V2 deadline exists yet. Do not persist the legacy sentinel.
  locked_time := clock_timestamp();
  insert into public.team_locks (
    season_id, matchday_id, trainer_id, season_player_id, save_file_id, save_sha256,
    locked_at, deadline_at, is_late, public_team_snapshot, private_team_snapshot
  ) values (
    p_season_id, p_matchday_id, p_trainer_id, p_season_player_id, p_save_file_id, save_row.sha256,
    locked_time, null, false, p_public_team_snapshot, p_private_team_snapshot
  )
  on conflict on constraint uq_team_locks_matchday_trainer do update set
    season_player_id = excluded.season_player_id,
    save_file_id = excluded.save_file_id,
    save_sha256 = excluded.save_sha256,
    locked_at = excluded.locked_at,
    deadline_at = excluded.deadline_at,
    is_late = excluded.is_late,
    public_team_snapshot = excluded.public_team_snapshot,
    private_team_snapshot = excluded.private_team_snapshot
  returning * into lock_row;

  insert into public.activity_events (
    season_id, type, actor_trainer_id, trainer_id, visibility, dedupe_key, context, payload, created_at
  ) values (
    p_season_id, 'TEAM_LOCKED', p_trainer_id, p_trainer_id, 'public',
    'TEAM_LOCKED:' || p_season_id::text || ':' || p_matchday_id::text || ':' || p_trainer_id::text,
    jsonb_build_object('season_id', p_season_id, 'matchday_id', p_matchday_id, 'matchday_number', matchday_row.number),
    jsonb_build_object(
      'lock_id', lock_row.id, 'matchday_number', matchday_row.number,
      'save_id', p_save_file_id, 'save_sha256', save_row.sha256, 'is_late', lock_row.is_late
    ), locked_time
  )
  on conflict (dedupe_key) where dedupe_key is not null and dedupe_key <> '' do nothing;

  return next lock_row;
end;
$$;

revoke all on function public.api_upsert_team_lock(uuid, uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb, jsonb) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function public.api_upsert_team_lock(uuid, uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb, jsonb) from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on function public.api_upsert_team_lock(uuid, uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb, jsonb) from authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.api_upsert_team_lock(uuid, uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb, jsonb) to service_role;
  end if;
end;
$$;

comment on function public.api_upsert_team_lock(uuid, uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb, jsonb) is
  'Backend-only atomic Team Lock replacement and deduplicated TEAM_LOCKED event. Snapshots are projected by the application from the compared parsed payload.';

commit;
-- ============================================================================
-- END 019_team_lock_api.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 020_current_matchday_store_ban_contract.sql
-- ============================================================================
-- Explicit competitive round and typed inclusive penalty windows. No backfill.
begin;

alter table public.seasons add column if not exists current_matchday_id uuid;
alter table public.penalties add column if not exists start_matchday_number integer;
alter table public.penalties add column if not exists end_matchday_number integer;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid='public.seasons'::regclass and conname='fk_seasons_current_matchday_same_season') then
    alter table public.seasons add constraint fk_seasons_current_matchday_same_season
      foreign key (current_matchday_id, id) references public.matchdays(id, season_id) on delete restrict;
  end if;
  if not exists (select 1 from pg_constraint where conrelid='public.penalties'::regclass and conname='penalties_window_chk') then
    alter table public.penalties add constraint penalties_window_chk check (
      (start_matchday_number is null or start_matchday_number > 0)
      and (end_matchday_number is null or end_matchday_number > 0)
      and (start_matchday_number is null or end_matchday_number is null or start_matchday_number <= end_matchday_number)
    );
  end if;
end;
$$;

comment on column public.seasons.current_matchday_id is
  'Server-owned competitive jornada, not inferred from status/order. Future season creation and close/advance operations maintain this pointer transactionally.';
comment on column public.penalties.start_matchday_number is
  'Inclusive store-ban start. If either boundary is NULL, preserve legacy active no-window compatibility.';
comment on column public.penalties.end_matchday_number is
  'Inclusive store-ban end. resolved_at alone does not cancel a store ban.';

-- Preserve prior admin column rights, but the new pointer is backend-owned.
do $$
declare prior_columns text;
begin
  select string_agg(quote_ident(attname), ', ' order by attnum) into prior_columns
  from pg_attribute where attrelid='public.seasons'::regclass
    and attnum > 0 and not attisdropped and attname <> 'current_matchday_id';
  revoke insert, update on public.seasons from authenticated;
  execute format('grant insert (%s), update (%s) on public.seasons to authenticated', prior_columns, prior_columns);
end;
$$;

create or replace function public.api_resolve_current_matchday(p_season_id uuid)
returns setof public.matchdays
language plpgsql security invoker set search_path = '' as $$
declare
  season_row public.seasons%rowtype;
  day_row public.matchdays%rowtype;
begin
  select * into season_row from public.seasons where id=p_season_id for share;
  if not found then raise sqlstate 'PT404' using message='season_not_found'; end if;
  if season_row.current_matchday_id is null then
    raise sqlstate 'PT409' using message='current_matchday_required';
  end if;
  select * into day_row from public.matchdays
    where id=season_row.current_matchday_id and season_id=p_season_id for share;
  if not found or day_row.status='cancelled' then
    raise sqlstate 'PT409' using message='current_matchday_invalid';
  end if;
  -- A closed pointer is authoritative until the future advance transaction moves it.
  return next day_row;
end;
$$;

create or replace function public.api_is_store_banned(p_season_id uuid, p_trainer_id uuid, p_matchday_number integer)
returns boolean
language sql security invoker set search_path = '' as $$
  select exists (
    select 1 from public.penalties p join public.trial_cases c on c.id=p.trial_case_id
    where p.season_id=p_season_id and p.trainer_id=p_trainer_id
      and p.penalty_type='store_ban' and c.status='resolved'
      and c.accused_trainer_id=p_trainer_id and (c.season_id is null or c.season_id=p_season_id)
      and (p.start_matchday_number is null or p.end_matchday_number is null
           or p_matchday_number between p.start_matchday_number and p.end_matchday_number)
  );
$$;

revoke all on function public.api_resolve_current_matchday(uuid) from public, anon, authenticated;
revoke all on function public.api_is_store_banned(uuid, uuid, integer) from public, anon, authenticated;
grant execute on function public.api_resolve_current_matchday(uuid) to service_role;
grant execute on function public.api_is_store_banned(uuid, uuid, integer) to service_role;
commit;
-- ============================================================================
-- END 020_current_matchday_store_ban_contract.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 021_normal_purchase_api.sql
-- ============================================================================
-- Backend-only normal purchase. Existing migrations and RLS remain unchanged.
begin;

alter table public.purchases add column if not exists idempotency_key text;
alter table public.purchases add column if not exists balance_after bigint;
-- NULL means confirmation was irrelevant to the original request.
alter table public.purchases add column if not exists base_price_confirmed boolean;
create unique index if not exists uq_purchases_idempotency
  on public.purchases (season_id, trainer_id, idempotency_key)
  where idempotency_key is not null;

create or replace function public.api_create_normal_purchase(
  p_season_id uuid, p_trainer_id uuid, p_item_id uuid,
  p_idempotency_key text, p_confirm_base_price boolean default false
) returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare
  v_trainer public.trainers%rowtype;
  v_season public.seasons%rowtype;
  v_player public.season_players%rowtype;
  v_day public.matchdays%rowtype;
  v_item public.shop_items%rowtype;
  v_promo public.shop_promotions%rowtype;
  v_purchase public.purchases%rowtype;
  v_balance bigint;
  v_confirmation boolean := false;
  v_ledger uuid := gen_random_uuid();
  v_event uuid := gen_random_uuid();
begin
  if p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128
     or p_idempotency_key !~ '^[!-~]+$' or p_confirm_base_price is null then
    raise sqlstate 'PT409' using message = 'invalid_purchase_request';
  end if;
  select * into v_trainer from public.trainers where id = p_trainer_id for share;
  if not found or not v_trainer.globally_enabled then
    raise sqlstate 'PT403' using message = 'trainer_disabled';
  end if;
  select * into v_season from public.seasons where id = p_season_id for share;
  if not found then raise sqlstate 'PT404' using message = 'season_not_found'; end if;
  -- Every future mutation of this wallet must acquire this same lock first.
  select * into v_player from public.season_players
    where season_id = p_season_id and trainer_id = p_trainer_id for update;
  if not found or v_player.status <> 'active' then
    raise sqlstate 'PT403' using message = 'participant_inactive';
  end if;
  select * into v_purchase from public.purchases
    where season_id = p_season_id and trainer_id = p_trainer_id and idempotency_key = p_idempotency_key;
  if found then
    if v_purchase.shop_item_id <> p_item_id or
       (v_purchase.base_price_confirmed is not null and v_purchase.base_price_confirmed <> p_confirm_base_price) then
      raise sqlstate 'PT409' using message = 'idempotency_conflict';
    end if;
    -- A retry is a receipt lookup, not a new charge at today's price or balance.
  else
    if v_season.status <> 'active' then raise sqlstate 'PT409' using message = 'season_not_active'; end if;
    select * into v_day from public.api_resolve_current_matchday(p_season_id);
    if public.api_is_store_banned(p_season_id, p_trainer_id, v_day.number) then
      raise sqlstate 'PT403' using message = 'store_banned';
    end if;
    select * into v_item from public.shop_items where id = p_item_id for share;
    if not found then raise sqlstate 'PT404' using message = 'item_not_found'; end if;
    if not v_item.enabled or v_item.base_price <= 0 then
      raise sqlstate 'PT409' using message = 'item_unavailable';
    end if;
    for v_promo in select * from public.shop_promotions
      where season_id = p_season_id and shop_item_id = p_item_id
        and matchday_id = v_day.id and status <> 'cancelled'
      order by id for share
    loop
      if exists (select 1 from public.purchases where promotion_id = v_promo.id
                 and season_id = p_season_id and trainer_id = p_trainer_id) then
        continue;
      end if;
      if v_promo.status in ('ended', 'exhausted') or v_promo.stock_used >= v_promo.stock_total
         or v_promo.ends_at <= statement_timestamp() then
        v_confirmation := true;
      elsif v_promo.activates_at > statement_timestamp()
         or (v_promo.status = 'pending' and v_promo.activates_at is null) then
        if v_item.category <> 'comodines' then
          raise sqlstate 'PT409' using message = 'promotion_pending';
        end if;
      else
        raise sqlstate 'PT409' using message = 'promotion_available';
      end if;
    end loop;
    if v_confirmation and not p_confirm_base_price then
      raise sqlstate 'PT409' using message = 'base_price_confirmation_required';
    end if;
    select coalesce(sum(amount), 0) into v_balance from public.coin_transactions
      where season_id = p_season_id and trainer_id = p_trainer_id;
    if v_balance < v_item.base_price then
      raise sqlstate 'PT409' using message = 'insufficient_funds';
    end if;
    insert into public.purchases (season_id, trainer_id, season_player_id, shop_item_id,
      quantity, unit_price, status, idempotency_key, balance_after, base_price_confirmed, metadata)
    values (p_season_id, p_trainer_id, v_player.id, p_item_id, 1, v_item.base_price, 'pending',
      p_idempotency_key, v_balance - v_item.base_price, case when v_confirmation then true else null end,
      jsonb_build_object('normal_purchase', jsonb_build_object('ledger_id', v_ledger, 'event_id', v_event,
        'matchday_id', v_day.id, 'matchday_number', v_day.number, 'item_name', v_item.name)))
    returning * into v_purchase;
    insert into public.coin_transactions (id, season_id, trainer_id, season_player_id, amount,
      transaction_type, reference_type, reference_id, created_by_trainer_id)
    values (v_ledger, p_season_id, p_trainer_id, v_player.id, -v_item.base_price,
      'purchase', 'purchase', v_purchase.id, p_trainer_id);
    insert into public.activity_events (id, season_id, type, actor_trainer_id, trainer_id,
      visibility, dedupe_key, context, payload)
    values (v_event, p_season_id, 'PURCHASE_COMPLETED', p_trainer_id, p_trainer_id, 'public',
      'purchase_completed:' || v_purchase.id::text,
      jsonb_build_object('matchday_number', v_day.number, 'matchday_id', v_day.id, 'base_price_confirmed', v_confirmation),
      jsonb_build_object('item', v_item.name, 'price', v_item.base_price, 'purchase_id', v_purchase.id,
        'quantity', 1, 'base_price', v_item.base_price, 'promotion_id', null, 'promotion_kind', ''));
  end if;
  return jsonb_build_object('id', v_purchase.id, 'season_id', v_purchase.season_id,
    'trainer_id', v_purchase.trainer_id, 'season_player_id', v_purchase.season_player_id,
    'item_id', v_purchase.shop_item_id, 'quantity', v_purchase.quantity,
    'unit_price', v_purchase.unit_price, 'total_price', v_purchase.total_price,
    'status', 'pending', 'purchased_at', v_purchase.purchased_at, 'balance_after', v_purchase.balance_after,
    'ledger_id', v_purchase.metadata #>> '{normal_purchase,ledger_id}',
    'event_id', v_purchase.metadata #>> '{normal_purchase,event_id}',
    'matchday_id', v_purchase.metadata #>> '{normal_purchase,matchday_id}',
    'matchday_number', (v_purchase.metadata #>> '{normal_purchase,matchday_number}')::integer);
end;
$$;

revoke all on function public.api_create_normal_purchase(uuid, uuid, uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.api_create_normal_purchase(uuid, uuid, uuid, text, boolean) to service_role;
comment on function public.api_create_normal_purchase(uuid, uuid, uuid, text, boolean) is
  'Backend-only atomic base purchase. Serializes wallet debits; no promotion claim, redemption or external effects.';
comment on column public.purchases.balance_after is 'Historical receipt snapshot, never the current wallet balance.';
comment on column public.purchases.base_price_confirmed is 'NULL when irrelevant; true only for explicitly confirmed promotional fallback.';
commit;
-- ============================================================================
-- END 021_normal_purchase_api.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 022_promotional_purchase_api.sql
-- ============================================================================
-- Atomic promotional claims; no rewrites of migrations 001-021.
begin;

create unique index if not exists uq_purchases_promotion_trainer
  on public.purchases (promotion_id, trainer_id) where promotion_id is not null;

-- The consumed counter is now an economic mutation, not a browser-admin field.
do $$ declare writable_columns text; begin
  select string_agg(quote_ident(attname), ', ' order by attnum) into writable_columns
    from pg_attribute where attrelid='public.shop_promotions'::regclass
      and attnum > 0 and not attisdropped and attname <> 'stock_used';
  revoke insert, update on public.shop_promotions from authenticated;
  execute format('grant insert (%s), update (%s) on public.shop_promotions to authenticated', writable_columns, writable_columns);
end; $$;

-- Keep the exact 8D implementation, adding only cross-operation replay isolation.
-- Rename once instead of copying/editing its SQL body in this migration.
do $$ begin
  if to_regprocedure('public.api_create_normal_purchase_8d(uuid,uuid,uuid,text,boolean)') is null then
    alter function public.api_create_normal_purchase(uuid,uuid,uuid,text,boolean)
      rename to api_create_normal_purchase_8d;
  end if;
end; $$;
create or replace function public.api_create_normal_purchase(
  p_season_id uuid, p_trainer_id uuid, p_item_id uuid,
  p_idempotency_key text, p_confirm_base_price boolean default false
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare receipt jsonb;
begin
  receipt := public.api_create_normal_purchase_8d(p_season_id,p_trainer_id,p_item_id,p_idempotency_key,p_confirm_base_price);
  if exists (select 1 from public.purchases where id=(receipt->>'id')::uuid and promotion_id is not null) then
    raise sqlstate 'PT409' using message='idempotency_conflict';
  end if;
  return receipt;
end; $$;

create or replace function public.api_create_promotional_purchase(
  p_season_id uuid, p_trainer_id uuid, p_promotion_id uuid, p_idempotency_key text
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  v_trainer public.trainers%rowtype;
  v_season public.seasons%rowtype;
  v_player public.season_players%rowtype;
  v_day public.matchdays%rowtype;
  v_item public.shop_items%rowtype;
  v_promo public.shop_promotions%rowtype;
  v_purchase public.purchases%rowtype;
  v_balance bigint;
  v_now timestamptz;
  v_ledger uuid := gen_random_uuid();
  v_event uuid := gen_random_uuid();
  v_history jsonb;
begin
  if p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128
     or p_idempotency_key !~ '^[!-~]+$' or p_promotion_id is null then
    raise sqlstate 'PT409' using message='invalid_purchase_request';
  end if;
  select * into v_trainer from public.trainers where id=p_trainer_id for share;
  if not found or not v_trainer.globally_enabled then raise sqlstate 'PT403' using message='trainer_disabled'; end if;
  select * into v_season from public.seasons where id=p_season_id for share;
  if not found then raise sqlstate 'PT404' using message='season_not_found'; end if;
  -- Same order as 8D: trainer/season -> wallet -> day -> item -> promotion.
  select * into v_player from public.season_players where season_id=p_season_id and trainer_id=p_trainer_id for update;
  if not found or v_player.status <> 'active' then raise sqlstate 'PT403' using message='participant_inactive'; end if;
  select * into v_purchase from public.purchases
    where season_id=p_season_id and trainer_id=p_trainer_id and idempotency_key=p_idempotency_key;
  if found then
    if v_purchase.promotion_id is distinct from p_promotion_id then
      raise sqlstate 'PT409' using message='idempotency_conflict';
    end if;
  else
    if v_season.status <> 'active' then raise sqlstate 'PT409' using message='season_not_active'; end if;
    select * into v_day from public.api_resolve_current_matchday(p_season_id);
    if public.api_is_store_banned(p_season_id,p_trainer_id,v_day.number) then
      raise sqlstate 'PT403' using message='store_banned';
    end if;
    -- Unlocked lookup discovers the item; all promotion facts are re-read under lock.
    select * into v_promo from public.shop_promotions where id=p_promotion_id and season_id=p_season_id;
    if not found then raise sqlstate 'PT404' using message='promotion_not_found'; end if;
    select * into v_item from public.shop_items where id=v_promo.shop_item_id for share;
    if not found or not v_item.enabled or v_item.base_price <= 0 then
      raise sqlstate 'PT409' using message='item_unavailable';
    end if;
    select * into v_promo from public.shop_promotions where id=p_promotion_id and season_id=p_season_id for update;
    if not found then raise sqlstate 'PT404' using message='promotion_not_found'; end if;
    if v_promo.shop_item_id <> v_item.id then raise sqlstate 'PT409' using message='promotion_changed'; end if;
    if v_promo.matchday_id is distinct from v_day.id then raise sqlstate 'PT409' using message='promotion_not_current'; end if;
    if exists (select 1 from public.purchases where promotion_id=p_promotion_id and trainer_id=p_trainer_id) then
      raise sqlstate 'PT409' using message='promotion_already_claimed';
    end if;
    -- Time is sampled after waiting for stock, not at request/transaction start.
    v_now := clock_timestamp();
    if v_promo.status in ('ended','cancelled') or v_promo.ends_at <= v_now then
      raise sqlstate 'PT409' using message='promotion_expired';
    end if;
    if v_promo.status='exhausted' or v_promo.stock_used >= v_promo.stock_total then
      raise sqlstate 'PT409' using message='promotion_exhausted';
    end if;
    if v_promo.activates_at > v_now or (v_promo.status='pending' and v_promo.activates_at is null) then
      raise sqlstate 'PT409' using message='promotion_pending';
    end if;
    if v_promo.effective_price <= 0 or v_promo.effective_price > v_promo.base_price then
      raise sqlstate 'PT409' using message='promotion_price_invalid';
    end if;
    select coalesce(sum(amount),0) into v_balance from public.coin_transactions
      where season_id=p_season_id and trainer_id=p_trainer_id;
    if v_balance < v_promo.effective_price then raise sqlstate 'PT409' using message='insufficient_funds'; end if;
    update public.shop_promotions set stock_used=stock_used+1,
      status=case when stock_used+1=stock_total then 'exhausted' else 'active' end,
      exhausted_at=case when stock_used+1=stock_total then v_now else exhausted_at end
      where id=p_promotion_id returning * into v_promo;
    v_history := jsonb_build_object('ledger_id',v_ledger,'event_id',v_event,'matchday_id',v_day.id,
      'matchday_number',v_day.number,'item_name',v_item.name,'base_price',v_promo.base_price,
      'promotion_kind',v_promo.promotion_type,'remaining_stock',v_promo.stock_total-v_promo.stock_used);
    insert into public.purchases(season_id,trainer_id,season_player_id,shop_item_id,promotion_id,
      quantity,unit_price,status,idempotency_key,balance_after,metadata)
    values(p_season_id,p_trainer_id,v_player.id,v_item.id,p_promotion_id,1,v_promo.effective_price,'pending',
      p_idempotency_key,v_balance-v_promo.effective_price,jsonb_build_object('promotional_purchase',v_history))
    returning * into v_purchase;
    insert into public.coin_transactions(id,season_id,trainer_id,season_player_id,amount,transaction_type,reference_type,reference_id,created_by_trainer_id)
    values(v_ledger,p_season_id,p_trainer_id,v_player.id,-v_promo.effective_price,'purchase','purchase',v_purchase.id,p_trainer_id);
    insert into public.activity_events(id,season_id,type,actor_trainer_id,trainer_id,visibility,dedupe_key,context,payload)
    values(v_event,p_season_id,'PURCHASE_COMPLETED',p_trainer_id,p_trainer_id,'public','purchase_completed:'||v_purchase.id::text,
      jsonb_build_object('matchday_id',v_day.id,'matchday_number',v_day.number),
      jsonb_build_object('purchase_id',v_purchase.id,'item',v_item.name,'quantity',1,'price',v_promo.effective_price,
        'base_price',v_promo.base_price,'promotion_id',p_promotion_id,'promotion_kind',v_promo.promotion_type));
  end if;
  v_history := v_purchase.metadata->'promotional_purchase';
  return jsonb_build_object('id',v_purchase.id,'season_id',v_purchase.season_id,'trainer_id',v_purchase.trainer_id,
    'season_player_id',v_purchase.season_player_id,'item_id',v_purchase.shop_item_id,'quantity',v_purchase.quantity,
    'unit_price',v_purchase.unit_price,'total_price',v_purchase.total_price,'status','pending',
    'purchased_at',v_purchase.purchased_at,'balance_after',v_purchase.balance_after,'promotion_id',v_purchase.promotion_id)
    || (v_history - 'item_name');
end; $$;

revoke all on function public.api_create_normal_purchase_8d(uuid,uuid,uuid,text,boolean) from public,anon,authenticated;
revoke all on function public.api_create_normal_purchase(uuid,uuid,uuid,text,boolean) from public,anon,authenticated;
revoke all on function public.api_create_promotional_purchase(uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.api_create_normal_purchase_8d(uuid,uuid,uuid,text,boolean) to service_role;
grant execute on function public.api_create_normal_purchase(uuid,uuid,uuid,text,boolean) to service_role;
grant execute on function public.api_create_promotional_purchase(uuid,uuid,uuid,text) to service_role;
comment on function public.api_create_promotional_purchase(uuid,uuid,uuid,text) is
  'Atomic claim/stock/purchase/debit/event. Wallet before stock; one claim per trainer, no redemption or base fallback.';
commit;
-- ============================================================================
-- END 022_promotional_purchase_api.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 023_pokemon_identity.sql
-- ============================================================================
-- PokeApp-owned identity. Raw evidence is private; no runtime or redemption wiring.
begin;

create table public.pokemon_entities (
  id uuid primary key,
  season_id uuid not null references public.seasons(id) on delete restrict,
  owner_trainer_id uuid not null references public.trainers(id) on delete restrict,
  identity_status text not null check (identity_status in ('unambiguous','missing','ambiguous')),
  identity_schema_version integer not null check (identity_schema_version = 1),
  candidate_key text not null check (candidate_key ~ '^[a-f0-9]{64}$'),
  initial_evidence jsonb not null check (jsonb_typeof(initial_evidence) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(id, season_id),
  foreign key (season_id, owner_trainer_id) references public.season_players(season_id, trainer_id)
);
create index pokemon_entities_owner_idx on public.pokemon_entities(season_id, owner_trainer_id, candidate_key);

alter table public.parsed_saves add constraint uq_parsed_saves_identity_file unique(id, save_file_id);
create table public.pokemon_identity_revisions (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  trainer_id uuid not null,
  save_file_id uuid not null unique,
  parsed_save_id uuid not null,
  predecessor_id uuid,
  revision_number bigint not null check(revision_number > 0),
  capture_stream_id uuid not null,
  capture_sequence bigint not null check(capture_sequence > 0),
  input_signature text not null check(input_signature ~ '^[a-f0-9]{64}$'),
  identity_schema_version integer not null default 1 check(identity_schema_version = 1),
  reconciliation_version integer not null default 1 check(reconciliation_version = 1),
  created_at timestamptz not null default now(),
  unique(id, season_id, trainer_id),
  unique(id, save_file_id, season_id, trainer_id),
  unique(season_id, trainer_id, revision_number),
  unique(season_id, trainer_id, capture_stream_id, capture_sequence),
  foreign key(save_file_id, season_id, trainer_id) references public.save_files(id, season_id, trainer_id),
  foreign key(parsed_save_id, save_file_id) references public.parsed_saves(id, save_file_id),
  foreign key(predecessor_id, season_id, trainer_id) references public.pokemon_identity_revisions(id, season_id, trainer_id),
  check ((revision_number = 1) = (predecessor_id is null))
);
create table public.pokemon_observations (
  id uuid primary key default gen_random_uuid(),
  revision_id uuid not null,
  season_id uuid not null,
  trainer_id uuid not null,
  save_file_id uuid not null,
  pokemon_entity_id uuid,
  source text not null check(source in ('party','box')),
  box_number integer not null,
  slot_number integer not null,
  outcome text not null check(outcome in ('NEW','MATCHED','AMBIGUOUS')),
  candidate_entity_ids uuid[] not null default '{}',
  evidence jsonb not null check(jsonb_typeof(evidence) = 'object'),
  candidate_key text not null check(candidate_key ~ '^[a-f0-9]{64}$'),
  observation_signature text not null check(observation_signature ~ '^[a-f0-9]{64}$'),
  legacy_fingerprints text[] not null default '{}',
  created_at timestamptz not null default now(),
  unique(save_file_id, source, box_number, slot_number),
  unique(save_file_id, pokemon_entity_id),
  foreign key(revision_id, save_file_id, season_id, trainer_id)
    references public.pokemon_identity_revisions(id, save_file_id, season_id, trainer_id),
  foreign key(pokemon_entity_id, season_id) references public.pokemon_entities(id, season_id),
  check((source='party' and box_number=0 and slot_number between 1 and 6)
     or (source='box' and box_number>0 and slot_number between 1 and 30)),
  check((outcome='AMBIGUOUS' and pokemon_entity_id is null and cardinality(candidate_entity_ids)>0)
     or (outcome<>'AMBIGUOUS' and pokemon_entity_id is not null and cardinality(candidate_entity_ids)=0))
);
create index pokemon_observations_revision_idx on public.pokemon_observations(revision_id);
create index pokemon_observations_entity_idx on public.pokemon_observations(pokemon_entity_id);

-- A link keeps the legacy flag/value authoritative. New flags need no invented fingerprint.
create table public.pokemon_entity_flags (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  trainer_id uuid not null,
  pokemon_entity_id uuid not null,
  flag_type text not null check(flag_type ~ '^[a-z0-9_]+$'),
  flag_value boolean,
  legacy_flag_id uuid unique references public.pokemon_flags(id) on delete restrict,
  created_at timestamptz not null default now(),
  unique(season_id, pokemon_entity_id, flag_type),
  foreign key(pokemon_entity_id, season_id) references public.pokemon_entities(id, season_id),
  foreign key(season_id, trainer_id) references public.season_players(season_id, trainer_id),
  check((legacy_flag_id is null) = (flag_value is not null))
);
create function public.check_pokemon_entity_flag() returns trigger
language plpgsql security invoker set search_path = '' as $$
begin
  if not exists(select 1 from public.pokemon_entities where id=new.pokemon_entity_id
    and season_id=new.season_id and owner_trainer_id=new.trainer_id) then
    raise check_violation using message='identity_flag_owner_mismatch'; end if;
  if new.legacy_flag_id is not null and not exists(select 1 from public.pokemon_flags
    where id=new.legacy_flag_id and season_id=new.season_id and trainer_id=new.trainer_id
    and flag_type=new.flag_type) then
    raise check_violation using message='identity_flag_legacy_mismatch'; end if;
  return new;
end $$;
revoke all on function public.check_pokemon_entity_flag() from public,anon,authenticated;
grant execute on function public.check_pokemon_entity_flag() to service_role;
create trigger pokemon_entity_flag_scope before insert or update on public.pokemon_entity_flags
for each row execute function public.check_pokemon_entity_flag();
comment on table public.pokemon_flags is
  'Legacy fingerprint flags, retained unchanged. Safe individual links live in pokemon_entity_flags; missing link means unresolved.';
comment on table public.pokemon_entities is
  'Season-scoped PokeApp UUID, not PID/OT/slot. Current ownership may change via a future audited command; observations retain historical owner.';
comment on table public.pokemon_identity_revisions is
  'Explicit CAS predecessor chain. Capture stream/sequence must be attested by backend; upload time alone is not game chronology.';

do $$ declare t text; owner_column text; begin
  foreach t in array array['pokemon_entities','pokemon_identity_revisions','pokemon_observations','pokemon_entity_flags'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('revoke all on public.%I from public, anon, authenticated',t);
    execute format('grant select on public.%I to authenticated',t);
    execute format('grant all on public.%I to service_role',t);
    owner_column := case when t='pokemon_entities' then 'owner_trainer_id' else 'trainer_id' end;
    execute format('create policy identity_private_read on public.%I for select to authenticated using
      (public.current_user_owns_trainer(%I) or public.is_current_user_admin())',t,owner_column);
  end loop;
end $$;

create function public.commit_pokemon_identity(p_request jsonb) returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare
  season uuid := (p_request->>'season_id')::uuid;
  trainer uuid := (p_request->>'trainer_id')::uuid;
  save_id uuid := (p_request->>'save_file_id')::uuid;
  head public.pokemon_identity_revisions;
  revision public.pokemon_identity_revisions;
  saved public.save_files;
  parsed public.parsed_saves;
  item jsonb;
  entity public.pokemon_entities;
  entity_id uuid;
  legacy public.pokemon_flags;
  targets uuid[];
  unresolved boolean;
  raw_pokemon jsonb;
  occurrence_count integer;
begin
  -- Shared player lock serializes concurrent workers across all saves of this owner.
  perform 1 from public.season_players where season_id=season and trainer_id=trainer for update;
  if not found then raise sqlstate 'PT404' using message='identity_player_not_found'; end if;
  select * into saved from public.save_files where id=save_id and season_id=season and trainer_id=trainer for share;
  if not found or saved.deleted_at is not null or saved.parser_status<>'parsed' then
    raise sqlstate 'PT409' using message='identity_save_not_ready'; end if;
  select * into parsed from public.parsed_saves where id=(p_request->>'parsed_save_id')::uuid
    and save_file_id=save_id for share;
  if not found or parsed.status<>'parsed' or parsed.payload is distinct from p_request->'parsed_payload'
    or parsed.parser_version is distinct from saved.parser_version then
    raise sqlstate 'PT409' using message='identity_parsed_source_changed'; end if;
  if jsonb_typeof(p_request->'bindings') is distinct from 'array'
    or (p_request->>'identity_schema_version')::int is distinct from 1
    or (p_request->>'reconciliation_version')::int is distinct from 1 then
    raise sqlstate 'PT409' using message='identity_invalid_plan'; end if;
  if jsonb_typeof(parsed.payload->'party') is distinct from 'array'
    or jsonb_typeof(parsed.payload->'boxes') is distinct from 'array' then
    raise sqlstate 'PT409' using message='identity_incomplete_payload'; end if;
  select count(*) into occurrence_count from (
    select s->'pokemon' p from jsonb_array_elements(parsed.payload->'party') s
    union all select s->'pokemon' from jsonb_array_elements(parsed.payload->'boxes') b,
      lateral jsonb_array_elements(b->'slots') s
  ) occurrences where p is not null and p<>'null'::jsonb;
  if occurrence_count <> jsonb_array_length(p_request->'bindings') then
    raise sqlstate 'PT409' using message='identity_incomplete_plan'; end if;

  select * into revision from public.pokemon_identity_revisions where save_file_id=save_id;
  if found then
    if revision.input_signature is distinct from p_request->>'input_signature' then
      raise sqlstate 'PT409' using message='identity_reparse_requires_review'; end if;
  else
    select * into head from public.pokemon_identity_revisions where season_id=season and trainer_id=trainer
      order by revision_number desc limit 1;
    if head.id is distinct from (p_request->>'expected_predecessor_id')::uuid then
      raise sqlstate 'PT409' using message='identity_head_changed'; end if;
    if p_request->>'capture_stream_id' is null or p_request->>'capture_sequence' is null then
      raise sqlstate 'PT409' using message='trusted_capture_order_required'; end if;
    if head.id is not null and (head.capture_stream_id is distinct from (p_request->>'capture_stream_id')::uuid
      or head.capture_sequence >= (p_request->>'capture_sequence')::bigint
      or saved.uploaded_at <= (select uploaded_at from public.save_files where id=head.save_file_id)) then
      raise sqlstate 'PT409' using message='identity_out_of_order'; end if;

    insert into public.pokemon_identity_revisions(season_id,trainer_id,save_file_id,parsed_save_id,
      predecessor_id,revision_number,capture_stream_id,capture_sequence,input_signature)
    values(season,trainer,save_id,parsed.id,head.id,coalesce(head.revision_number,0)+1,
      (p_request->>'capture_stream_id')::uuid,(p_request->>'capture_sequence')::bigint,p_request->>'input_signature')
    returning * into revision;

    update public.pokemon_entities set identity_status='missing',updated_at=now()
      where season_id=season and owner_trainer_id=trainer and identity_status='unambiguous';
    for item in select value from jsonb_array_elements(p_request->'bindings') loop
      raw_pokemon := null;
      if item->>'source'='party' then
        select s->'pokemon' into raw_pokemon from jsonb_array_elements(parsed.payload->'party') s
          where s->>'slot_number'=item->>'slot_number';
      else
        select s->'pokemon' into raw_pokemon from jsonb_array_elements(parsed.payload->'boxes') b,
          lateral jsonb_array_elements(b->'slots') s where b->>'box_number'=item->>'box_number'
          and s->>'slot_number'=item->>'slot_number';
      end if;
      if raw_pokemon is null or raw_pokemon->'identity_evidence' is distinct from item->'evidence' then
        raise sqlstate 'PT409' using message='identity_evidence_source_mismatch'; end if;
      entity_id := (item->>'pokemon_entity_id')::uuid;
      if item->>'outcome'='NEW' then
        if exists(select 1 from public.pokemon_entities e where e.season_id=season and e.owner_trainer_id=trainer
          and e.initial_evidence->>'pid'=item->'evidence'->>'pid' and not exists
          (select 1 from public.pokemon_observations o where o.revision_id=revision.id and o.pokemon_entity_id=e.id)) then
          raise sqlstate 'PT409' using message='identity_new_has_prior_candidate'; end if;
        insert into public.pokemon_entities(id,season_id,owner_trainer_id,identity_status,
          identity_schema_version,candidate_key,initial_evidence)
        values(entity_id,season,trainer,'unambiguous',1,item->>'candidate_key',item->'evidence');
      elsif item->>'outcome'='MATCHED' then
        if (select count(*) from public.pokemon_entities e where e.season_id=season and e.owner_trainer_id=trainer
          and e.initial_evidence->>'pid'=item->'evidence'->>'pid') <> 1
          or (select count(*) from jsonb_array_elements(p_request->'bindings') b
            where b->'evidence'->>'pid'=item->'evidence'->>'pid') <> 1 then
          raise sqlstate 'PT409' using message='identity_multiple_candidates'; end if;
        select * into entity from public.pokemon_entities where id=entity_id and season_id=season
          and owner_trainer_id=trainer and candidate_key=item->>'candidate_key' for update;
        if not found or entity.identity_status='ambiguous' then
          raise sqlstate 'PT409' using message='identity_invalid_binding'; end if;
        update public.pokemon_entities set identity_status='unambiguous',updated_at=now() where id=entity_id;
      elsif item->>'outcome'='AMBIGUOUS' then
        for entity_id in select value::uuid from jsonb_array_elements_text(item->'candidate_entity_ids') loop
          update public.pokemon_entities set identity_status='ambiguous',updated_at=now()
            where id=entity_id and season_id=season and owner_trainer_id=trainer
              and initial_evidence->>'pid'=item->'evidence'->>'pid';
          if not found then raise sqlstate 'PT409' using message='identity_invalid_candidate'; end if;
        end loop;
      else raise sqlstate 'PT409' using message='identity_invalid_outcome'; end if;
      insert into public.pokemon_observations(revision_id,season_id,trainer_id,save_file_id,
        pokemon_entity_id,source,box_number,slot_number,outcome,candidate_entity_ids,evidence,
        candidate_key,observation_signature,legacy_fingerprints)
      values(revision.id,season,trainer,save_id,(item->>'pokemon_entity_id')::uuid,item->>'source',
        (item->>'box_number')::int,(item->>'slot_number')::int,item->>'outcome',
        array(select value::uuid from jsonb_array_elements_text(item->'candidate_entity_ids')),
        item->'evidence',item->>'candidate_key',item->>'observation_signature',
        array(select value from jsonb_array_elements_text(item->'legacy_fingerprints')));
    end loop;

    -- Consider all retained observations in THIS chain/scope, never choose first/all on a collision.
    for legacy in select * from public.pokemon_flags where season_id=season and trainer_id=trainer for share loop
      select array_agg(distinct pokemon_entity_id) filter(where pokemon_entity_id is not null),
        bool_or(pokemon_entity_id is null) into targets,unresolved
      from public.pokemon_observations where season_id=season and trainer_id=trainer
        and legacy.fingerprint=any(legacy_fingerprints);
      if cardinality(targets)=1 and not coalesce(unresolved,false) then
        insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,legacy_flag_id)
        values(season,trainer,targets[1],legacy.flag_type,legacy.id) on conflict do nothing;
      end if;
    end loop;
  end if;
  return jsonb_build_object('revision',to_jsonb(revision),'observations',coalesce(
    (select jsonb_agg(to_jsonb(o) order by source,box_number,slot_number)
     from public.pokemon_observations o where revision_id=revision.id),'[]'::jsonb));
end $$;
revoke all on function public.commit_pokemon_identity(jsonb) from public, anon, authenticated;
grant execute on function public.commit_pokemon_identity(jsonb) to service_role;

commit;
-- ============================================================================
-- END 023_pokemon_identity.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 024_redemption_effect_boundary.sql
-- ============================================================================
-- Backend-only entitlement consumption. No physical save operation.
begin;

alter table public.redemptions
  add column idempotency_key text,
  add column effect_code text,
  add column target_pokemon_entity_id uuid,
  add column target_owner_trainer_id uuid references public.trainers(id),
  add column identity_revision_id uuid references public.pokemon_identity_revisions(id),
  add column physical_effect_status text,
  add column physical_effect_completed_at timestamptz,
  add column requested_at timestamptz,
  add column activity_event_id uuid references public.activity_events(id) deferrable initially deferred,
  add column receipt jsonb,
  add constraint redemption_entity_season_fk foreign key(target_pokemon_entity_id,season_id)
    references public.pokemon_entities(id,season_id),
  add constraint redemption_purchase_unique unique(purchase_id),
  add constraint redemption_boundary_chk check (
    (idempotency_key is null and effect_code is null and target_pokemon_entity_id is null
      and target_owner_trainer_id is null and identity_revision_id is null
      and physical_effect_status is null and physical_effect_completed_at is null
      and requested_at is null and activity_event_id is null and receipt is null)
    or
    (idempotency_key is not null and length(idempotency_key) between 1 and 128
      and idempotency_key ~ '^[!-~]+$' and effect_code is not null
      and target_pokemon_entity_id is not null and target_owner_trainer_id is not null
      and identity_revision_id is not null and requested_at is not null
      and activity_event_id is not null and receipt is not null and jsonb_typeof(receipt)='object'
      and physical_effect_status is not null and physical_effect_completed_at is null
      and ((effect_code='shield' and physical_effect_status='not_required')
        or (effect_code='revive' and physical_effect_status='pending')))
  );
create unique index redemption_idempotency_idx
  on public.redemptions(season_id,trainer_id,purchase_id,idempotency_key)
  where idempotency_key is not null;

-- Preserve timestamp semantics: revivido_at is NOT a new boolean flag.
alter table public.pokemon_entity_flags add column flag_timestamp timestamptz;
alter table public.pokemon_entity_flags drop constraint pokemon_entity_flags_check;
alter table public.pokemon_entity_flags add constraint pokemon_entity_flag_value_chk check (
  (legacy_flag_id is not null and flag_value is null and flag_timestamp is null)
  or (legacy_flag_id is null and flag_value is not null and flag_timestamp is null)
  or (legacy_flag_id is null and flag_value is null and flag_timestamp is not null and flag_type='revivido_at')
);

-- Previously some admin browser writes were allowed. All effect surfaces are backend-only now.
revoke insert,update,delete,truncate on public.purchases,public.redemptions,
  public.pokemon_entities,public.pokemon_observations,public.pokemon_entity_flags,
  public.trainer_flags,public.activity_events from public,anon,authenticated;

create function public.api_redeem_purchase(
  p_season_id uuid, p_trainer_id uuid, p_purchase_id uuid, p_pokemon_entity_id uuid,
  p_idempotency_key text, p_expected_revision_id uuid
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare
  v_player public.season_players;
  v_purchase public.purchases;
  v_redemption public.redemptions;
  v_entity public.pokemon_entities;
  v_head public.pokemon_identity_revisions;
  v_observation public.pokemon_observations;
  v_code text;
  v_effect text;
  v_physical text;
  v_id uuid := gen_random_uuid();
  v_event uuid := gen_random_uuid();
  v_now timestamptz := transaction_timestamp();
  v_receipt jsonb;
begin
  if p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128
    or p_idempotency_key !~ '^[!-~]+$' or p_pokemon_entity_id is null then
    raise sqlstate 'PT409' using message='invalid_redemption_request'; end if;
  perform 1 from public.trainers where id=p_trainer_id and globally_enabled for share;
  if not found then raise sqlstate 'PT403' using message='trainer_disabled'; end if;
  perform 1 from public.seasons where id=p_season_id for share;
  if not found then raise sqlstate 'PT404' using message='season_not_found'; end if;
  -- Shared ordering with identity and purchase RPCs: participant, purchase, entity, flags.
  select * into v_player from public.season_players
    where season_id=p_season_id and trainer_id=p_trainer_id for update;
  if not found or v_player.status<>'active' then
    raise sqlstate 'PT403' using message='participant_inactive'; end if;
  select * into v_purchase from public.purchases where id=p_purchase_id
    and season_id=p_season_id and trainer_id=p_trainer_id for update;
  if not found then raise sqlstate 'PT404' using message='purchase_not_found'; end if;
  select * into v_redemption from public.redemptions where purchase_id=v_purchase.id;
  if found then
    if v_redemption.idempotency_key is distinct from p_idempotency_key then
      raise sqlstate 'PT409' using message='purchase_already_redeemed'; end if;
    if v_redemption.target_pokemon_entity_id is distinct from p_pokemon_entity_id then
      raise sqlstate 'PT409' using message='idempotency_conflict'; end if;
    return v_redemption.receipt;
  end if;
  if v_purchase.status<>'pending' or v_purchase.quantity<>1 then
    raise sqlstate 'PT409' using message='purchase_not_redeemable'; end if;
  select code into v_code from public.shop_items where id=v_purchase.shop_item_id for share;
  v_effect := case v_code when 'blindar_pokemon' then 'shield' when 'revivir_pokemon' then 'revive' end;
  -- No authoritative gift item exists in 001-023. Never invent a code or a partial theft.
  if v_effect is null then raise sqlstate 'PT409' using message='redemption_not_supported'; end if;
  select * into v_entity from public.pokemon_entities where id=p_pokemon_entity_id
    and season_id=p_season_id and owner_trainer_id=p_trainer_id for update;
  if not found then raise sqlstate 'PT409' using message='pokemon_not_owned'; end if;
  select * into v_head from public.pokemon_identity_revisions
    where season_id=p_season_id and trainer_id=p_trainer_id order by revision_number desc limit 1 for share;
  if not found or v_entity.identity_status<>'unambiguous' then
    raise sqlstate 'PT409' using message='pokemon_identity_ambiguous'; end if;
  if v_head.id is distinct from p_expected_revision_id then
    raise sqlstate 'PT409' using message='pokemon_target_stale'; end if;
  select * into v_observation from public.pokemon_observations
    where revision_id=v_head.id and pokemon_entity_id=v_entity.id
      and trainer_id=p_trainer_id and season_id=p_season_id and outcome in ('NEW','MATCHED') for share;
  if not found then raise sqlstate 'PT409' using message='pokemon_identity_ambiguous'; end if;
  if v_observation.source='box' and v_observation.box_number not between 1 and 8 then
    raise sqlstate 'PT409' using message='invalid_pokemon_target'; end if;
  if v_effect='revive' and not (v_observation.source='box' and v_observation.box_number=8) then
    raise sqlstate 'PT409' using message='pokemon_not_revivable'; end if;
  if v_effect='shield' and exists (
    select 1 from public.pokemon_entity_flags f left join public.pokemon_flags l on l.id=f.legacy_flag_id
    where f.season_id=p_season_id and f.pokemon_entity_id=v_entity.id and f.flag_type='blindado'
      and coalesce(f.flag_value,l.flag_value,false)
  ) then raise sqlstate 'PT409' using message='pokemon_already_shielded'; end if;

  v_physical := case v_effect when 'revive' then 'pending' else 'not_required' end;
  v_receipt := jsonb_build_object('redemption_id',v_id,'purchase_id',v_purchase.id,
    'season_id',p_season_id,'trainer_id',p_trainer_id,'shop_item_id',v_purchase.shop_item_id,
    'effect_code',v_effect,'target_pokemon_entity_id',v_entity.id,'target_owner_trainer_id',v_entity.owner_trainer_id,
    'purchase_status','used','redemption_status','applied','physical_effect_status',v_physical,
    'requested_at',v_now,'redeemed_at',v_now,'physical_effect_completed_at',null,
    'activity_event_id',v_event,'gift_purchase_id',null);
  insert into public.redemptions(id,purchase_id,season_id,trainer_id,season_player_id,shop_item_id,
    redemption_type,status,payload,redeemed_at,idempotency_key,effect_code,target_pokemon_entity_id,
    target_owner_trainer_id,identity_revision_id,physical_effect_status,requested_at,activity_event_id,receipt)
  values(v_id,v_purchase.id,p_season_id,p_trainer_id,v_player.id,v_purchase.shop_item_id,
    v_effect,'applied',jsonb_build_object('item_code',v_code,'effect_code',v_effect,
      'target_pokemon_entity_id',v_entity.id,'target_owner_trainer_id',v_entity.owner_trainer_id),v_now,
    p_idempotency_key,v_effect,v_entity.id,v_entity.owner_trainer_id,v_head.id,v_physical,v_now,v_event,v_receipt);
  insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,flag_value)
    values(p_season_id,p_trainer_id,v_entity.id,'blindado',true)
    on conflict(season_id,pokemon_entity_id,flag_type) do update
      set flag_value=true,legacy_flag_id=null,flag_timestamp=null;
  if v_effect='revive' then
    insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,flag_timestamp)
      values(p_season_id,p_trainer_id,v_entity.id,'revivido_at',v_now)
      on conflict(season_id,pokemon_entity_id,flag_type) do update
        set flag_timestamp=v_now,flag_value=null,legacy_flag_id=null;
  end if;
  update public.purchases set status='used' where id=v_purchase.id;
  insert into public.activity_events(id,season_id,type,actor_trainer_id,trainer_id,visibility,dedupe_key,payload)
    values(v_event,p_season_id,'REDEMPTION_USED',p_trainer_id,p_trainer_id,'owner',
      'redemption_used:'||v_id::text,v_receipt);
  return v_receipt;
end $$;
revoke all on function public.api_redeem_purchase(uuid,uuid,uuid,uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.api_redeem_purchase(uuid,uuid,uuid,uuid,text,uuid) to service_role;
comment on column public.redemptions.physical_effect_status is
  'used/applied consumes the entitlement and applies internal effects, NOT a physical save write. Companion must start from redemption_id.';
commit;
-- ============================================================================
-- END 024_redemption_effect_boundary.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 025_robbery_voucher_and_redemption.sql
-- ============================================================================
-- Canonical reward and atomic robbery. No physical transfer or save writes.
begin;

alter table public.shop_items add column acquisition_mode text not null default 'purchasable',
  add constraint shop_item_acquisition_chk check (
    acquisition_mode='purchasable' or
    (acquisition_mode='reward_only' and base_price=0 and not enabled)),
  add constraint shop_item_voucher_chk check (code<>'robbery_shield_voucher'
    or (acquisition_mode='reward_only' and category='comodines'));
-- enabled is SHOP availability, not the ability to redeem an owned entitlement.
-- Both existing purchase RPCs reject disabled/zero-price items under their item lock.
insert into public.shop_items(code,name,category,base_price,enabled,acquisition_mode)
values('robbery_shield_voucher',U&'Comod\00EDn de Blindaje por Robo','comodines',0,false,'reward_only')
on conflict(code) do nothing;

alter table public.purchases
  add column acquisition_type text not null default 'paid',
  add column origin_redemption_id uuid unique references public.redemptions(id),
  add constraint purchase_acquisition_chk check (
    (acquisition_type='paid' and unit_price>0 and origin_redemption_id is null)
    or (acquisition_type='reward' and unit_price=0 and quantity=1 and promotion_id is null
      and origin_redemption_id is not null and idempotency_key is null and balance_after is null
      and base_price_confirmed is null));

alter table public.redemptions
  add column gift_purchase_id uuid references public.purchases(id) deferrable initially deferred,
  add column robbery_cycle_number bigint,
  drop constraint redemption_boundary_chk,
  add constraint redemption_boundary_chk check (
    (idempotency_key is null and effect_code is null and target_pokemon_entity_id is null
      and target_owner_trainer_id is null and identity_revision_id is null
      and physical_effect_status is null and physical_effect_completed_at is null
      and requested_at is null and activity_event_id is null and receipt is null
      and gift_purchase_id is null and robbery_cycle_number is null)
    or
    (idempotency_key is not null and length(idempotency_key) between 1 and 128
      and idempotency_key ~ '^[!-~]+$' and effect_code is not null
      and target_pokemon_entity_id is not null and target_owner_trainer_id is not null
      and identity_revision_id is not null and requested_at is not null
      and activity_event_id is not null and receipt is not null and jsonb_typeof(receipt)='object'
      and physical_effect_status is not null and physical_effect_completed_at is null
      and ((effect_code in ('shield','robbery_shield') and physical_effect_status='not_required'
          and gift_purchase_id is null and robbery_cycle_number is null and target_owner_trainer_id=trainer_id)
        or (effect_code='revive' and physical_effect_status='pending' and gift_purchase_id is null
          and robbery_cycle_number is null and target_owner_trainer_id=trainer_id)
        or (effect_code='steal' and physical_effect_status='pending' and gift_purchase_id is not null
          and robbery_cycle_number is not null and robbery_cycle_number>0 and target_owner_trainer_id<>trainer_id)))
  );
create unique index robbery_victim_cycle_idx
  on public.redemptions(season_id,robbery_cycle_number,target_owner_trainer_id)
  where effect_code='steal';

create table public.robbery_cycles (
  season_id uuid primary key references public.seasons(id),
  cycle_number bigint not null default 1 check(cycle_number>0),
  last_redemption_id uuid references public.redemptions(id),
  history_watermark_id uuid references public.redemptions(id)
);
alter table public.robbery_cycles enable row level security;
revoke all on public.robbery_cycles from public,anon,authenticated;
grant all on public.robbery_cycles to service_role;
comment on table public.robbery_cycles is
  'Backend-only cycle cursor; redemptions retain immutable victim history. No browser access.';

alter table public.pokemon_entity_flags
  add column flag_trainer_id uuid references public.trainers(id),
  drop constraint pokemon_entity_flag_value_chk,
  add constraint pokemon_entity_flag_value_chk check (
    (legacy_flag_id is not null and flag_value is null and flag_timestamp is null and flag_trainer_id is null)
    or (legacy_flag_id is null and flag_value is not null and flag_timestamp is null and flag_trainer_id is null)
    or (legacy_flag_id is null and flag_value is null and flag_timestamp is not null
      and flag_trainer_id is null and flag_type in ('revivido_at','robado_at'))
    or (legacy_flag_id is null and flag_value is null and flag_timestamp is null
      and flag_trainer_id is not null and flag_type='robado_from')
  );

-- Protect the reward path even for backend direct inserts, not only the HTTP API.
create function public.check_purchase_acquisition() returns trigger
language plpgsql security invoker set search_path='' as $$
declare v_item public.shop_items; v_origin public.redemptions;
begin
  select * into v_item from public.shop_items where id=new.shop_item_id for share;
  if new.acquisition_type='paid' and v_item.acquisition_mode<>'purchasable' then
    raise sqlstate 'PT409' using message='item_unavailable'; end if;
  if new.acquisition_type='reward' then
    select * into v_origin from public.redemptions where id=new.origin_redemption_id;
    if not found or v_item.code<>'robbery_shield_voucher' or v_item.acquisition_mode<>'reward_only'
      or v_origin.effect_code is distinct from 'steal' or v_origin.status<>'applied'
      or v_origin.season_id<>new.season_id or v_origin.trainer_id<>new.trainer_id
      or v_origin.season_player_id<>new.season_player_id or v_origin.gift_purchase_id is distinct from new.id then
      raise sqlstate 'PT409' using message='invalid_reward_origin'; end if;
  end if;
  return new;
end $$;
create trigger purchase_acquisition_guard before insert or update on public.purchases
for each row execute function public.check_purchase_acquisition();
revoke all on function public.check_purchase_acquisition() from public,anon,authenticated;
grant execute on function public.check_purchase_acquisition() to service_role;

create or replace function public.api_redeem_purchase(
  p_season_id uuid, p_trainer_id uuid, p_purchase_id uuid, p_pokemon_entity_id uuid,
  p_idempotency_key text, p_expected_revision_id uuid
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare
  v_player public.season_players;
  v_victim public.season_players;
  v_purchase public.purchases;
  v_redemption public.redemptions;
  v_entity public.pokemon_entities;
  v_head public.pokemon_identity_revisions;
  v_observation public.pokemon_observations;
  v_cycle public.robbery_cycles;
  v_active uuid[];
  v_code text;
  v_effect text;
  v_physical text;
  v_gift uuid;
  v_voucher uuid;
  v_id uuid := gen_random_uuid();
  v_event uuid := gen_random_uuid();
  v_now timestamptz := transaction_timestamp();
  v_receipt jsonb;
begin
  if p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128
    or p_idempotency_key !~ '^[!-~]+$' or p_pokemon_entity_id is null then
    raise sqlstate 'PT409' using message='invalid_redemption_request'; end if;
  perform 1 from public.trainers where id=p_trainer_id and globally_enabled for share;
  if not found then raise sqlstate 'PT403' using message='trainer_disabled'; end if;
  -- Serialize the cycle before any wallet lock. NO KEY UPDATE remains compatible
  -- with FK KEY SHARE locks taken by an in-flight identity reconciliation.
  perform 1 from public.seasons where id=p_season_id for no key update;
  if not found then raise sqlstate 'PT404' using message='season_not_found'; end if;
  v_active := array[]::uuid[];
  for v_player in select * from public.season_players where season_id=p_season_id order by id for update loop
    if v_player.status='active' then v_active:=array_append(v_active,v_player.trainer_id); end if;
  end loop;
  select * into v_player from public.season_players where season_id=p_season_id and trainer_id=p_trainer_id;
  if not found or v_player.status<>'active' then
    raise sqlstate 'PT403' using message='participant_inactive'; end if;
  select * into v_purchase from public.purchases where id=p_purchase_id
    and season_id=p_season_id and trainer_id=p_trainer_id for update;
  if not found then raise sqlstate 'PT404' using message='purchase_not_found'; end if;
  select * into v_redemption from public.redemptions where purchase_id=v_purchase.id;
  if found then
    if v_redemption.idempotency_key is distinct from p_idempotency_key then
      raise sqlstate 'PT409' using message='purchase_already_redeemed'; end if;
    if v_redemption.target_pokemon_entity_id is distinct from p_pokemon_entity_id then
      raise sqlstate 'PT409' using message='idempotency_conflict'; end if;
    return v_redemption.receipt;
  end if;
  if v_purchase.status<>'pending' or v_purchase.quantity<>1 then
    raise sqlstate 'PT409' using message='purchase_not_redeemable'; end if;
  select code into v_code from public.shop_items where id=v_purchase.shop_item_id for share;
  v_effect := case v_code when 'blindar_pokemon' then 'shield' when 'revivir_pokemon' then 'revive'
    when 'robbery_shield_voucher' then 'robbery_shield' when 'robar_pokemon' then 'steal' end;
  if v_effect is null then raise sqlstate 'PT409' using message='redemption_not_supported'; end if;
  select * into v_entity from public.pokemon_entities where id=p_pokemon_entity_id
    and season_id=p_season_id for update;
  if not found then raise sqlstate 'PT409' using message='pokemon_not_owned'; end if;
  if v_effect='steal' then
    if v_entity.owner_trainer_id=p_trainer_id then
      raise sqlstate 'PT409' using message='steal_self_target'; end if;
    select * into v_victim from public.season_players
      where season_id=p_season_id and trainer_id=v_entity.owner_trainer_id;
    if not found or not (v_victim.trainer_id=any(v_active)) then
      raise sqlstate 'PT409' using message='steal_victim_ineligible'; end if;
  elsif v_entity.owner_trainer_id<>p_trainer_id then
    raise sqlstate 'PT409' using message='pokemon_not_owned';
  end if;
  select * into v_head from public.pokemon_identity_revisions
    where season_id=p_season_id and trainer_id=v_entity.owner_trainer_id
    order by revision_number desc limit 1 for share;
  if not found or v_entity.identity_status<>'unambiguous' then
    raise sqlstate 'PT409' using message='pokemon_identity_ambiguous'; end if;
  if v_head.id is distinct from p_expected_revision_id then
    raise sqlstate 'PT409' using message='pokemon_target_stale'; end if;
  select * into v_observation from public.pokemon_observations
    where revision_id=v_head.id and pokemon_entity_id=v_entity.id
      and trainer_id=v_entity.owner_trainer_id and season_id=p_season_id
      and outcome in ('NEW','MATCHED') for share;
  if not found then raise sqlstate 'PT409' using message='pokemon_identity_ambiguous'; end if;
  if v_effect='steal' and v_observation.source='box' and v_observation.box_number not between 1 and 7 then
    raise sqlstate 'PT409' using message='steal_target_ineligible'; end if;
  if v_observation.source='box' and v_observation.box_number not between 1 and 8 then
    raise sqlstate 'PT409' using message='invalid_pokemon_target'; end if;
  if v_effect='revive' and not (v_observation.source='box' and v_observation.box_number=8) then
    raise sqlstate 'PT409' using message='pokemon_not_revivable'; end if;
  if v_effect<>'revive' and exists (
    select 1 from public.pokemon_entity_flags f left join public.pokemon_flags l on l.id=f.legacy_flag_id
    where f.season_id=p_season_id and f.pokemon_entity_id=v_entity.id and f.flag_type='blindado'
      and coalesce(f.flag_value,l.flag_value,false)
  ) then
    if v_effect='steal' then raise sqlstate 'PT409' using message='steal_target_shielded'; end if;
    raise sqlstate 'PT409' using message='pokemon_already_shielded';
  end if;

  if v_effect='steal' then
    insert into public.robbery_cycles(season_id) values(p_season_id) on conflict do nothing;
    select * into v_cycle from public.robbery_cycles where season_id=p_season_id for update;
    -- Legacy also checks completeness BEFORE selection, e.g. after a retirement.
    if not exists (select 1 from unnest(v_active) t(id) where not exists (
      select 1 from public.redemptions r where r.season_id=p_season_id
        and r.robbery_cycle_number=v_cycle.cycle_number and r.target_owner_trainer_id=t.id)) then
      update public.robbery_cycles set cycle_number=cycle_number+1,history_watermark_id=last_redemption_id
        where season_id=p_season_id returning * into v_cycle;
      update public.trainer_flags set flag_value=false,payload='{}' where season_id=p_season_id
        and flag_type='robbed' and trainer_id=any(v_active);
    end if;
    if exists (select 1 from public.redemptions where season_id=p_season_id
      and robbery_cycle_number=v_cycle.cycle_number and target_owner_trainer_id=v_entity.owner_trainer_id) then
      raise sqlstate 'PT409' using message='steal_victim_already_robbed'; end if;
    select id into v_voucher from public.shop_items where code='robbery_shield_voucher'
      and acquisition_mode='reward_only' for share;
    if not found then raise sqlstate 'PT409' using message='steal_cycle_conflict'; end if;
    v_gift:=gen_random_uuid();
  end if;
  v_physical := case when v_effect in ('revive','steal') then 'pending' else 'not_required' end;
  v_receipt := jsonb_build_object('redemption_id',v_id,'purchase_id',v_purchase.id,
    'season_id',p_season_id,'trainer_id',p_trainer_id,'shop_item_id',v_purchase.shop_item_id,
    'effect_code',v_effect,'target_pokemon_entity_id',v_entity.id,'target_owner_trainer_id',v_entity.owner_trainer_id,
    'purchase_status','used','redemption_status','applied','physical_effect_status',v_physical,
    'requested_at',v_now,'redeemed_at',v_now,'physical_effect_completed_at',null,
    'activity_event_id',v_event,'gift_purchase_id',v_gift);
  insert into public.redemptions(id,purchase_id,season_id,trainer_id,season_player_id,shop_item_id,
    redemption_type,status,payload,redeemed_at,idempotency_key,effect_code,target_pokemon_entity_id,
    target_owner_trainer_id,identity_revision_id,physical_effect_status,requested_at,activity_event_id,receipt,
    gift_purchase_id,robbery_cycle_number)
  values(v_id,v_purchase.id,p_season_id,p_trainer_id,v_player.id,v_purchase.shop_item_id,
    v_effect,'applied',jsonb_build_object('item_code',v_code,'effect_code',v_effect,
      'target_pokemon_entity_id',v_entity.id,'target_owner_trainer_id',v_entity.owner_trainer_id),v_now,
    p_idempotency_key,v_effect,v_entity.id,v_entity.owner_trainer_id,v_head.id,v_physical,v_now,v_event,v_receipt,
    v_gift,v_cycle.cycle_number);
  insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,flag_value)
    values(p_season_id,v_entity.owner_trainer_id,v_entity.id,'blindado',true)
    on conflict(season_id,pokemon_entity_id,flag_type) do update
      set flag_value=true,legacy_flag_id=null,flag_timestamp=null,flag_trainer_id=null;
  if v_effect in ('revive','steal') then
    insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,flag_timestamp)
      values(p_season_id,v_entity.owner_trainer_id,v_entity.id,
        case v_effect when 'revive' then 'revivido_at' else 'robado_at' end,v_now)
      on conflict(season_id,pokemon_entity_id,flag_type) do update
        set flag_timestamp=v_now,flag_value=null,legacy_flag_id=null,flag_trainer_id=null;
  end if;
  if v_effect in ('steal','robbery_shield') then
    insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,flag_value)
      values(p_season_id,v_entity.owner_trainer_id,v_entity.id,
        case v_effect when 'steal' then 'robado' else 'blindaje_por_robo' end,true)
      on conflict(season_id,pokemon_entity_id,flag_type) do update
        set flag_value=true,legacy_flag_id=null,flag_timestamp=null,flag_trainer_id=null;
  end if;
  if v_effect='steal' then
    insert into public.pokemon_entity_flags(season_id,trainer_id,pokemon_entity_id,flag_type,flag_trainer_id)
      values(p_season_id,v_entity.owner_trainer_id,v_entity.id,'robado_from',v_entity.owner_trainer_id)
      on conflict(season_id,pokemon_entity_id,flag_type) do update
        set flag_trainer_id=excluded.flag_trainer_id,flag_value=null,flag_timestamp=null,legacy_flag_id=null;
    insert into public.trainer_flags(season_id,trainer_id,season_player_id,flag_type,flag_value,payload)
      values(p_season_id,v_victim.trainer_id,v_victim.id,'robbed',true,
        jsonb_build_object('robbed_at',v_now,'robbed_by',p_trainer_id,'robbed_source','live',
          'redemption_id',v_id,'cycle_number',v_cycle.cycle_number))
      on conflict(season_id,trainer_id,flag_type) do update set flag_value=true,payload=excluded.payload;
    update public.robbery_cycles set last_redemption_id=v_id where season_id=p_season_id;
    if not exists (select 1 from unnest(v_active) t(id) where not exists (
      select 1 from public.redemptions r where r.season_id=p_season_id
        and r.robbery_cycle_number=v_cycle.cycle_number and r.target_owner_trainer_id=t.id)) then
      update public.robbery_cycles set cycle_number=cycle_number+1,history_watermark_id=v_id where season_id=p_season_id;
      update public.trainer_flags set flag_value=false,payload='{}' where season_id=p_season_id
        and flag_type='robbed' and trainer_id=any(v_active);
    end if;
    insert into public.purchases(id,season_id,trainer_id,season_player_id,shop_item_id,
      quantity,unit_price,status,acquisition_type,origin_redemption_id)
      values(v_gift,p_season_id,p_trainer_id,v_player.id,v_voucher,1,0,'pending','reward',v_id);
  end if;
  update public.purchases set status='used' where id=v_purchase.id;
  insert into public.activity_events(id,season_id,type,actor_trainer_id,trainer_id,visibility,dedupe_key,payload)
    values(v_event,p_season_id,'REDEMPTION_USED',p_trainer_id,p_trainer_id,'owner',
      'redemption_used:'||v_id::text,v_receipt);
  return v_receipt;
end $$;
revoke all on function public.api_redeem_purchase(uuid,uuid,uuid,uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.api_redeem_purchase(uuid,uuid,uuid,uuid,text,uuid) to service_role;
commit;
-- ============================================================================
-- END 025_robbery_voucher_and_redemption.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 026_season_admin_setup_api.sql
-- ============================================================================
-- Phase 8G.1: backend-only season preparation. No competitive close or rewards.
begin;

create table public.season_admin_state (
  season_id uuid primary key references public.seasons(id) on delete restrict,
  setup_revision bigint not null default 0 check (setup_revision >= 0),
  roster_revision bigint not null default 0 check (roster_revision >= 0),
  config_revision bigint not null default 0 check (config_revision >= 0)
);
create table public.admin_operation_receipts (
  id uuid primary key default gen_random_uuid(),
  actor_trainer_id uuid not null references public.trainers(id) on delete restrict,
  season_id uuid not null references public.seasons(id) on delete restrict,
  operation_scope text not null,
  idempotency_key text not null check (length(idempotency_key) between 1 and 128),
  request_hash text not null,
  response_json jsonb not null check (jsonb_typeof(response_json) = 'object'),
  created_at timestamptz not null default now(),
  unique (actor_trainer_id, operation_scope, idempotency_key)
);
alter table public.season_admin_state enable row level security;
alter table public.admin_operation_receipts enable row level security;
revoke all on public.season_admin_state, public.admin_operation_receipts from public, anon, authenticated;
grant all on public.season_admin_state, public.admin_operation_receipts to service_role;

-- NULL identifies pre-026 fixtures/imports, never a validated admin configuration.
alter table public.season_config_versions
  add column division_sizes jsonb,
  add column roster_revision bigint check (roster_revision >= 0),
  add constraint config_division_sizes_shape check (division_sizes is null or
    (jsonb_typeof(division_sizes) = 'object' and division_sizes ?& array['A','B']
     and division_sizes - 'A' - 'B' = '{}'::jsonb
     and (division_sizes->>'A')::integer > 0 and (division_sizes->>'B')::integer > 0));
create unique index uq_matches_unordered_pair on public.matches
  (matchday_id, least(player_a_id,player_b_id), greatest(player_a_id,player_b_id));

-- Table revocation alone does not remove the column grants introduced by 020.
revoke insert, update, delete on public.seasons, public.season_players,
  public.season_player_stats, public.season_config_versions, public.divisions,
  public.division_memberships, public.matchdays, public.matches from public, anon, authenticated;
do $$ declare t text; c text; begin
  foreach t in array array['seasons','season_players','season_player_stats',
    'season_config_versions','divisions','division_memberships','matchdays','matches'] loop
    select string_agg(quote_ident(attname), ',') into c from pg_attribute
      where attrelid=('public.'||t)::regclass and attnum>0 and not attisdropped;
    execute format('revoke insert (%s), update (%s) on public.%I from public, anon, authenticated',c,c,t);
  end loop;
end $$;

create function public.admin_setup_fail(code text, status integer default 409)
returns void language plpgsql set search_path = pg_catalog, public as $$
begin raise exception using errcode='PT'||status::text, message=code; end $$;

create function public.admin_setup_principal(actor uuid) returns void
language plpgsql set search_path = pg_catalog, public as $$
declare t public.trainers;
begin
  select * into t from public.trainers where id=actor for share;
  if not found or not t.globally_enabled then perform public.admin_setup_fail('trainer_disabled',403); end if;
  if not t.is_admin then perform public.admin_setup_fail('admin_required',403); end if;
end $$;

create function public.admin_setup_receipt_immutable() returns trigger
language plpgsql set search_path = pg_catalog, public as $$
begin
  if new is distinct from old then perform public.admin_setup_fail('idempotency_conflict'); end if;
  return new;
end $$;
create trigger admin_receipt_immutable before update on public.admin_operation_receipts
  for each row execute function public.admin_setup_receipt_immutable();

create function public.admin_setup_scope(op text, r jsonb) returns text
language sql immutable set search_path = pg_catalog as $$
  select op||':'||coalesce(r->>'season_id','new')||':'||coalesce(r->>'resource_id','')
$$;

create function public.admin_setup_begin(op text, r jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare old public.admin_operation_receipts; sid uuid=(r->>'season_id')::uuid;
  scope text=public.admin_setup_scope(op,r); k text=r->>'idempotency_key';
begin
  perform public.admin_setup_principal((r->>'actor_trainer_id')::uuid);
  if k is null or length(k) not between 1 and 128 then
    perform public.admin_setup_fail('invalid_request',422);
  end if;
  -- Receipts serialize retries even before a season exists. All operations use
  -- this order: principal, receipt key, season, participant UUIDs, specific rows.
  perform pg_advisory_xact_lock(hashtextextended((r->>'actor_trainer_id')||scope||':'||k,0));
  select * into old from public.admin_operation_receipts
    where actor_trainer_id=(r->>'actor_trainer_id')::uuid and operation_scope=scope and idempotency_key=k;
  if found then
    if old.request_hash <> encode(sha256(convert_to(r::text,'UTF8')),'hex') then
      if op='rename' then perform public.admin_setup_fail('stale_revision'); end if;
      perform public.admin_setup_fail('idempotency_conflict');
    end if;
    return old.response_json || '{"replayed":true}'::jsonb;
  end if;
  if sid is not null then
    perform 1 from public.seasons where id=sid for no key update;
    if not found then perform public.admin_setup_fail('season_not_found',404); end if;
    perform 1 from public.season_admin_state where season_id=sid;
    if not found then perform public.admin_setup_fail('setup_incomplete'); end if;
    perform 1 from public.season_players where season_id=sid order by id for update;
  end if;
  return null;
end $$;

create function public.admin_setup_finish(op text,r jsonb,sid uuid,resource uuid,evidence jsonb default '{}')
returns jsonb language plpgsql set search_path = pg_catalog, public as $$
declare oid uuid=gen_random_uuid(); eid uuid=gen_random_uuid(); result jsonb;
begin
  insert into public.activity_events(id,season_id,type,actor_trainer_id,visibility,dedupe_key,payload)
    values(eid,sid,'SEASON_ADMIN_'||upper(op),(r->>'actor_trainer_id')::uuid,'admin',
      'season-admin:'||oid::text,jsonb_build_object('operation_id',oid,'resource_id',resource,'evidence',evidence));
  select jsonb_build_object('operation_id',oid,'resource_id',resource,'season_id',sid,
    'event_id',eid,'replayed',false,'state',s.status,'setup_revision',a.setup_revision,
    'roster_revision',a.roster_revision,'config_revision',a.config_revision) into result
    from public.seasons s join public.season_admin_state a on a.season_id=s.id where s.id=sid;
  insert into public.admin_operation_receipts(id,actor_trainer_id,season_id,operation_scope,idempotency_key,request_hash,response_json)
    values(oid,(r->>'actor_trainer_id')::uuid,sid,public.admin_setup_scope(op,r),r->>'idempotency_key',
      encode(sha256(convert_to(r::text,'UTF8')),'hex'),result);
  return result;
end $$;

create function public.admin_setup_draft(sid uuid) returns void
language plpgsql set search_path = pg_catalog, public as $$
begin
  if not exists(select 1 from public.seasons where id=sid and status='draft') then
    perform public.admin_setup_fail('season_not_draft');
  end if;
end $$;

create function public.admin_setup_cas(sid uuid,b jsonb) returns void
language plpgsql set search_path = pg_catalog, public as $$
declare a public.season_admin_state;
begin
  select * into strict a from public.season_admin_state where season_id=sid;
  if (b ? 'expected_revision' and (b->>'expected_revision')::bigint<>a.setup_revision)
    or (b ? 'expected_setup_revision' and (b->>'expected_setup_revision')::bigint<>a.setup_revision)
    or (b ? 'expected_roster_revision' and (b->>'expected_roster_revision')::bigint<>a.roster_revision)
    or (b ? 'expected_config_revision' and (b->>'expected_config_revision')::bigint<>a.config_revision) then
    perform public.admin_setup_fail('stale_revision');
  end if;
end $$;

create function public.admin_setup_config_used(cid uuid) returns boolean
language sql stable set search_path = pg_catalog, public as $$
  select exists(select 1 from public.matchdays where season_config_version_id=cid)
    or exists(select 1 from public.matchday_snapshots where config_version_id=cid)
$$;
create function public.admin_setup_protect_config() returns trigger
language plpgsql set search_path = pg_catalog, public as $$
begin
  if public.admin_setup_config_used(old.id) and new is distinct from old then
    perform public.admin_setup_fail('config_already_used');
  end if;
  return new;
end $$;
create trigger config_used_immutable before update on public.season_config_versions
  for each row execute function public.admin_setup_protect_config();

create function public.admin_setup_validate_config(sid uuid,b jsonb) returns void
language plpgsql set search_path = pg_catalog, public as $$
declare n integer; a integer; z integer; effective integer; total integer; k text; rewards jsonb; v jsonb;
begin
  select count(*) into n from public.season_players where season_id=sid;
  if n=0 or exists(select 1 from public.season_players where season_id=sid and status<>'active') then
    perform public.admin_setup_fail('invalid_roster');
  end if;
  if jsonb_typeof(b->'division_sizes') is distinct from 'object'
     or not (b->'division_sizes' ?& array['A','B']) or (b->'division_sizes')-'A'-'B'<>'{}'::jsonb then
    perform public.admin_setup_fail('invalid_config');
  end if;
  a=(b->'division_sizes'->>'A')::integer; z=(b->'division_sizes'->>'B')::integer;
  effective=(b->>'effective_from_matchday')::integer; total=(b->>'total_matchdays')::integer;
  if a<=0 or z<=0 or a+z<>n or (b->>'movement_count')::integer not between 0 and least(a,z)
    or total<1 or effective not between 1 and total or length(btrim(b->>'name')) not between 1 and 120 then
    perform public.admin_setup_fail('invalid_config');
  end if;
  foreach k in array array['scoring','coin_rewards'] loop
    rewards=b->k;
    if jsonb_typeof(rewards) is distinct from 'object'
      or (select count(*) from jsonb_object_keys(rewards))<>n then
      perform public.admin_setup_fail('invalid_rewards');
    end if;
    for i in 1..n loop
      v=rewards->i::text;
      if jsonb_typeof(v) is distinct from 'number' or v::text !~ '^[0-9]+$' then
        perform public.admin_setup_fail('invalid_rewards');
      end if;
    end loop;
  end loop;
  if jsonb_typeof(b->'rules') is distinct from 'object' or
    (b->'rules')-'team_lock_required'-'last_b_gets_steal'<>'{}'::jsonb or
    jsonb_typeof(b->'rules'->'team_lock_required') is distinct from 'boolean' or
    jsonb_typeof(b->'rules'->'last_b_gets_steal') is distinct from 'boolean' then
    perform public.admin_setup_fail('invalid_config');
  end if;
end $$;

create function public.admin_setup_config_window(sid uuid,b jsonb) returns void
language plpgsql set search_path = pg_catalog, public as $$
begin
  if not exists(select 1 from public.seasons where id=sid and status in ('draft','active'))
    or (b->>'effective_from_matchday')::integer <= coalesce((select max(number) from public.matchdays where season_id=sid),0) then
    perform public.admin_setup_fail('config_window_closed');
  end if;
end $$;

create function public.api_admin_create_season(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid; b jsonb=p_request->'body';
begin
  cached=public.admin_setup_begin('create',p_request); if cached is not null then return cached; end if;
  if length(btrim(b->>'name')) not between 1 and 120 then perform public.admin_setup_fail('invalid_request',422); end if;
  insert into public.seasons(name,status,created_by_trainer_id)
    values(b->>'name','draft',(p_request->>'actor_trainer_id')::uuid) returning id into sid;
  insert into public.season_admin_state(season_id) values(sid);
  return public.admin_setup_finish('create',p_request,sid,sid);
end $$;

create function public.api_admin_rename_season(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body'; old_name text;
begin
  cached=public.admin_setup_begin('rename',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_draft(sid); perform public.admin_setup_cas(sid,b);
  if length(btrim(b->>'name')) not between 1 and 120 then perform public.admin_setup_fail('invalid_request',422); end if;
  select name into old_name from public.seasons where id=sid;
  update public.seasons set name=b->>'name' where id=sid;
  update public.season_admin_state set setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('rename',p_request,sid,sid,jsonb_build_object('before',old_name,'after',b->>'name'));
end $$;

create function public.api_admin_add_participant(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body'; pid uuid; tid uuid=(b->>'trainer_id')::uuid;
begin
  cached=public.admin_setup_begin('add_participant',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_draft(sid); perform public.admin_setup_cas(sid,b);
  if exists(select 1 from public.division_memberships where season_id=sid) or exists(select 1 from public.matchdays where season_id=sid) then
    perform public.admin_setup_fail('initial_setup_locked'); end if;
  if not exists(select 1 from public.trainers where id=tid and globally_enabled) then
    perform public.admin_setup_fail('trainer_unavailable'); end if;
  if exists(select 1 from public.season_players where season_id=sid and trainer_id=tid) then
    perform public.admin_setup_fail('participant_exists'); end if;
  insert into public.season_players(season_id,trainer_id,seed_order) values(sid,tid,(b->>'seed_order')::integer) returning id into pid;
  insert into public.season_player_stats(season_player_id,season_id,trainer_id) values(pid,sid,tid);
  update public.season_admin_state set roster_revision=roster_revision+1,setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('add_participant',p_request,sid,pid);
end $$;

create function public.api_admin_remove_participant(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; pid uuid=(p_request->>'resource_id')::uuid;
  b jsonb=p_request->'body'; ref record; referenced boolean;
begin
  cached=public.admin_setup_begin('remove_participant',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_draft(sid); perform public.admin_setup_cas(sid,b);
  if not exists(select 1 from public.season_players where id=pid and season_id=sid) then
    perform public.admin_setup_fail('participant_not_found',404); end if;
  if length(btrim(b->>'reason')) not between 1 and 500 then perform public.admin_setup_fail('invalid_request',422); end if;
  if exists(select 1 from public.season_config_versions where season_id=sid)
    or exists(select 1 from public.divisions where season_id=sid)
    or exists(select 1 from public.matchdays where season_id=sid)
    or exists(select 1 from public.season_players where id=pid and (current_save_file_id is not null or metadata<>'{}'::jsonb))
    or exists(select 1 from public.season_player_stats where season_player_id=pid and (badges_count<>0 or metadata<>'{}'::jsonb)) then
    perform public.admin_setup_fail('participant_referenced'); end if;
  -- Inspect every real FK to participant identity, including later additive tables.
  for ref in
    select c.conrelid::regclass as tbl,a.attname from pg_constraint c
    cross join lateral unnest(c.conkey,c.confkey) as cols(src,dst)
    join pg_attribute a on a.attrelid=c.conrelid and a.attnum=cols.src
    join pg_attribute target on target.attrelid=c.confrelid and target.attnum=cols.dst
    where c.contype='f' and c.confrelid='public.season_players'::regclass and target.attname='id'
      and c.conrelid<>'public.season_player_stats'::regclass
  loop
    execute format('select exists(select 1 from %s where %I=$1)',ref.tbl,ref.attname) into referenced using pid;
    if referenced then perform public.admin_setup_fail('participant_referenced'); end if;
  end loop;
  delete from public.season_player_stats where season_player_id=pid;
  delete from public.season_players where id=pid;
  update public.season_admin_state set roster_revision=roster_revision+1,setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('remove_participant',p_request,sid,pid,jsonb_build_object('reason',b->>'reason'));
exception when foreign_key_violation then perform public.admin_setup_fail('participant_referenced');
end $$;

create function public.api_admin_create_config(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body'; cid uuid;
begin
  cached=public.admin_setup_begin('create_config',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_cas(sid,b); perform public.admin_setup_validate_config(sid,b); perform public.admin_setup_config_window(sid,b);
  if exists(select 1 from public.season_config_versions where season_id=sid and effective_from_matchday=(b->>'effective_from_matchday')::integer) then
    perform public.admin_setup_fail('effective_round_exists'); end if;
  insert into public.season_config_versions(season_id,version_number,name,effective_from_matchday,total_matchdays,
    division_count,promotion_relegation_count,scoring_json,coin_rewards_json,rules_json,division_sizes,roster_revision,created_by_trainer_id)
    values(sid,(select coalesce(max(version_number),0)+1 from public.season_config_versions where season_id=sid),
      b->>'name',(b->>'effective_from_matchday')::integer,(b->>'total_matchdays')::integer,2,(b->>'movement_count')::integer,
      b->'scoring',b->'coin_rewards',b->'rules',b->'division_sizes',(b->>'expected_roster_revision')::bigint,(p_request->>'actor_trainer_id')::uuid)
    returning id into cid;
  update public.season_admin_state set config_revision=config_revision+1,setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('create_config',p_request,sid,cid);
end $$;

create function public.api_admin_replace_config(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body'; cid uuid=(p_request->>'resource_id')::uuid; old public.season_config_versions;
begin
  cached=public.admin_setup_begin('replace_config',p_request); if cached is not null then return cached; end if;
  select * into old from public.season_config_versions where id=cid and season_id=sid for update;
  if not found then perform public.admin_setup_fail('config_not_found',404); end if;
  if public.admin_setup_config_used(cid) then perform public.admin_setup_fail('config_already_used'); end if;
  perform public.admin_setup_cas(sid,b); perform public.admin_setup_validate_config(sid,b); perform public.admin_setup_config_window(sid,b);
  if old.effective_from_matchday<>(b->>'effective_from_matchday')::integer or length(btrim(b->>'reason')) not between 1 and 500 then
    perform public.admin_setup_fail('invalid_config'); end if;
  if old.effective_from_matchday=1 and exists(select 1 from public.division_memberships where season_id=sid)
    and old.division_sizes is distinct from b->'division_sizes' then perform public.admin_setup_fail('initial_setup_locked'); end if;
  update public.season_config_versions set name=b->>'name',total_matchdays=(b->>'total_matchdays')::integer,
    promotion_relegation_count=(b->>'movement_count')::integer,scoring_json=b->'scoring',coin_rewards_json=b->'coin_rewards',
    rules_json=b->'rules',division_sizes=b->'division_sizes',roster_revision=(b->>'expected_roster_revision')::bigint where id=cid;
  update public.season_admin_state set config_revision=config_revision+1,setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('replace_config',p_request,sid,cid,
    jsonb_build_object('reason',b->>'reason','before',to_jsonb(old),'after',b));
end $$;

create function public.api_admin_initial_divisions(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body'; cfg public.season_config_versions;
  division_code text; did uuid; pid text; all_ids uuid[]; n integer;
begin
  cached=public.admin_setup_begin('initial_divisions',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_draft(sid); perform public.admin_setup_cas(sid,b);
  if exists(select 1 from public.division_memberships where season_id=sid) or exists(select 1 from public.matchdays where season_id=sid) then
    perform public.admin_setup_fail('initial_setup_locked'); end if;
  select * into cfg from public.season_config_versions where id=(b->>'config_version_id')::uuid and season_id=sid;
  if not found or cfg.effective_from_matchday<>1 or cfg.division_sizes is null or cfg.roster_revision<>(b->>'expected_roster_revision')::bigint then
    perform public.admin_setup_fail('config_not_effective'); end if;
  if jsonb_typeof(b->'assignments') is distinct from 'object' or not(b->'assignments' ?& array['A','B'])
    or (b->'assignments')-'A'-'B'<>'{}'::jsonb then perform public.admin_setup_fail('invalid_roster'); end if;
  select array_agg(value::uuid) into all_ids from jsonb_array_elements_text((b->'assignments'->'A')||(b->'assignments'->'B'));
  select count(*) into n from public.season_players where season_id=sid and status='active';
  if cardinality(all_ids) is distinct from n or (select count(distinct x) from unnest(all_ids) x)<>n
    or exists(select 1 from unnest(all_ids) x where not exists(select 1 from public.season_players where id=x and season_id=sid and status='active')) then
    perform public.admin_setup_fail('invalid_roster'); end if;
  foreach division_code in array array['A','B'] loop
    if jsonb_array_length(b->'assignments'->division_code)<>(cfg.division_sizes->>division_code)::integer then
      perform public.admin_setup_fail('division_capacity_mismatch'); end if;
    insert into public.divisions(season_id,code,name,tier_order) values(sid,division_code,'Division '||division_code,case division_code when 'A' then 1 else 2 end)
      on conflict(season_id,code) do nothing;
    select id into did from public.divisions d where d.season_id=sid and d.code=division_code and tier_order=case division_code when 'A' then 1 else 2 end;
    if did is null then perform public.admin_setup_fail('initial_setup_locked'); end if;
    for pid in select jsonb_array_elements_text(b->'assignments'->division_code) loop
      insert into public.division_memberships(season_id,season_player_id,division_id,effective_from_matchday_number,reason)
        values(sid,pid::uuid,did,1,'initial');
    end loop;
  end loop;
  update public.season_admin_state set setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('initial_divisions',p_request,sid,sid);
end $$;

create function public.admin_setup_readiness(sid uuid) returns jsonb
language plpgsql stable set search_path = pg_catalog, public as $$
declare s public.seasons; a public.season_admin_state; cfg public.season_config_versions; day public.matchdays;
  n integer; okcfg boolean=false; members boolean=false; pairs boolean=false; divok boolean=false; checks jsonb; reasons jsonb;
begin
  select * into s from public.seasons where id=sid;
  select * into a from public.season_admin_state where season_id=sid;
  select count(*) into n from public.season_players where season_id=sid;
  select * into cfg from public.season_config_versions where season_id=sid and effective_from_matchday=1;
  if cfg.id is not null and cfg.roster_revision=a.roster_revision and cfg.division_sizes is not null then
    begin
      perform public.admin_setup_validate_config(sid,jsonb_build_object('name',cfg.name,'division_sizes',cfg.division_sizes,
        'effective_from_matchday',1,'total_matchdays',cfg.total_matchdays,'movement_count',cfg.promotion_relegation_count,
        'scoring',cfg.scoring_json,'coin_rewards',cfg.coin_rewards_json,'rules',cfg.rules_json));
      okcfg=true;
    exception when sqlstate 'PT409' then okcfg=false; end;
  end if;
  divok=(select count(*)=2 and bool_and((code='A' and tier_order=1) or (code='B' and tier_order=2)) from public.divisions where season_id=sid);
  members=divok and okcfg and (select count(*)=n from public.division_memberships where season_id=sid)
    and not exists(select 1 from public.division_memberships where season_id=sid and
      (effective_from_matchday_number<>1 or effective_to_matchday_number is not null or source_matchday_id is not null or reason<>'initial'))
    and not exists(select 1 from public.divisions d where d.season_id=sid and
      (select count(*) from public.division_memberships m where m.division_id=d.id)<>(cfg.division_sizes->>d.code)::integer);
  select * into day from public.matchdays where season_id=sid and number=1;
  if members and day.id is not null then
    with expected as (
      select m.division_id,m.season_player_id a,x.season_player_id b from public.division_memberships m
      join public.division_memberships x on x.division_id=m.division_id and m.season_player_id<x.season_player_id
      where m.season_id=sid
    ), actual as (
      select division_id,least(player_a_id,player_b_id) a,greatest(player_a_id,player_b_id) b
      from public.matches where matchday_id=day.id
    ) select not exists((select * from expected except select * from actual) union all
      (select * from actual except select * from expected)) into pairs;
    pairs=pairs and not exists(select 1 from public.matches where matchday_id=day.id and
      (status<>'scheduled' or winner_id is not null or result_code<>''));
  end if;
  checks=jsonb_build_object('has_roster',n>0 and not exists(select 1 from public.season_players p
      left join public.season_player_stats st on st.season_player_id=p.id where p.season_id=sid and (p.status<>'active' or st.season_player_id is null)),
    'has_valid_config',okcfg,'has_initial_divisions',divok,'memberships_complete',members,
    'first_matchday_prepared',day.id is not null and day.status='scheduled' and day.opened_at is null and day.closed_at is null
       and day.season_config_version_id=cfg.id and (select count(*)=1 from public.matchdays where season_id=sid),
    'match_pairs_complete',pairs,'pointer_valid',coalesce(s.current_matchday_id=day.id,false),
    'no_other_active_season',not exists(select 1 from public.seasons where status='active' and id<>sid),
    'is_draft',s.status='draft');
  select coalesce(jsonb_agg(key order by key),'[]'::jsonb) into reasons from jsonb_each(checks) where value is distinct from 'true'::jsonb;
  return jsonb_build_object('checks',checks,'blocking_reasons',reasons,'can_activate',reasons='[]'::jsonb);
end $$;

create function public.api_admin_prepare_first_matchday(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body'; ready jsonb; cid uuid; did uuid;
begin
  cached=public.admin_setup_begin('prepare',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_draft(sid);
  if exists(select 1 from public.matchdays where season_id=sid) then perform public.admin_setup_fail('matchday_already_prepared'); end if;
  perform public.admin_setup_cas(sid,b);
  ready=public.admin_setup_readiness(sid)->'checks';
  if not ((ready->>'has_roster')::boolean and (ready->>'has_valid_config')::boolean and (ready->>'memberships_complete')::boolean) then
    perform public.admin_setup_fail('setup_incomplete'); end if;
  select id into cid from public.season_config_versions where season_id=sid and effective_from_matchday=1;
  insert into public.matchdays(season_id,number,season_config_version_id) values(sid,1,cid) returning id into did;
  insert into public.matches(season_id,matchday_id,division_id,player_a_id,player_b_id)
    select sid,did,m.division_id,m.season_player_id,x.season_player_id from public.division_memberships m
    join public.division_memberships x on x.division_id=m.division_id and m.season_player_id<x.season_player_id
    where m.season_id=sid order by m.division_id,m.season_player_id,x.season_player_id;
  update public.seasons set current_matchday_id=did where id=sid;
  update public.season_admin_state set setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('prepare',p_request,sid,did);
end $$;

create function public.api_admin_activate_season(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare cached jsonb; sid uuid=(p_request->>'season_id')::uuid; b jsonb=p_request->'body';
begin
  cached=public.admin_setup_begin('activate',p_request); if cached is not null then return cached; end if;
  perform public.admin_setup_draft(sid); perform public.admin_setup_cas(sid,b);
  if exists(select 1 from public.seasons where status='active' and id<>sid) then perform public.admin_setup_fail('active_season_exists'); end if;
  if not (public.admin_setup_readiness(sid)->>'can_activate')::boolean then perform public.admin_setup_fail('setup_incomplete'); end if;
  begin
    update public.seasons set status='active',started_at=clock_timestamp() where id=sid;
  exception when unique_violation then perform public.admin_setup_fail('active_season_exists'); end;
  update public.season_admin_state set setup_revision=setup_revision+1 where season_id=sid;
  return public.admin_setup_finish('activate',p_request,sid,sid);
end $$;

create function public.api_admin_get_setup(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare sid uuid=(p_request->>'season_id')::uuid; result jsonb;
begin
  perform public.admin_setup_principal((p_request->>'actor_trainer_id')::uuid);
  -- SHARE holds a coherent multi-query read against every admin mutation.
  perform 1 from public.seasons where id=sid for share;
  if not found then perform public.admin_setup_fail('season_not_found',404); end if;
  select jsonb_build_object('season',jsonb_build_object('id',s.id,'name',s.name,'status',s.status,'started_at',s.started_at),
    'setup_revision',coalesce(a.setup_revision,0),'roster_revision',coalesce(a.roster_revision,0),'config_revision',coalesce(a.config_revision,0),
    'current_matchday_id',s.current_matchday_id,'readiness',public.admin_setup_readiness(sid),
    'participants',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'trainer_id',p.trainer_id,'display_name',t.display_name,
      'status',p.status,'seed_order',p.seed_order,'stats_ready',st.season_player_id is not null) order by p.id),'[]'::jsonb)
      from public.season_players p join public.trainers t on t.id=p.trainer_id
      left join public.season_player_stats st on st.season_player_id=p.id where p.season_id=sid),
    'config_versions',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'version_number',c.version_number,
      'effective_from_matchday',c.effective_from_matchday,'total_matchdays',c.total_matchdays,'division_sizes',c.division_sizes,
      'movement_count',c.promotion_relegation_count,'scoring',c.scoring_json,'coin_rewards',c.coin_rewards_json,'rules',c.rules_json,
      'roster_revision',c.roster_revision,'used',public.admin_setup_config_used(c.id),
      'is_current',coalesce(c.id=(select x.id from public.season_config_versions x where x.season_id=sid
        and x.effective_from_matchday<=coalesce((select number from public.matchdays where id=s.current_matchday_id),1)
        order by x.effective_from_matchday desc limit 1),false)) order by c.effective_from_matchday),'[]'::jsonb)
      from public.season_config_versions c where c.season_id=sid),
    'divisions',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'code',d.code,'tier_order',d.tier_order) order by d.tier_order),'[]'::jsonb) from public.divisions d where d.season_id=sid),
    'memberships',(select coalesce(jsonb_agg(jsonb_build_object('season_player_id',m.season_player_id,'division_id',m.division_id,
      'effective_from_matchday',m.effective_from_matchday_number,'effective_to_matchday',m.effective_to_matchday_number,'reason',m.reason) order by m.season_player_id),'[]'::jsonb) from public.division_memberships m where m.season_id=sid),
    'first_matchday',(select jsonb_build_object('id',d.id,'number',d.number,'status',d.status,'config_version_id',d.season_config_version_id,
      'match_count',(select count(*) from public.matches where matchday_id=d.id)) from public.matchdays d where d.season_id=sid and number=1)) into result
    from public.seasons s left join public.season_admin_state a on a.season_id=s.id where s.id=sid;
  return result;
end $$;

do $$ declare f regprocedure; begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and (p.proname like 'admin_setup_%' or p.proname like 'api_admin_%') loop
    execute format('revoke all on function %s from public, anon, authenticated',f);
    execute format('grant execute on function %s to service_role',f);
  end loop;
end $$;
notify pgrst, 'reload schema';
commit;
-- ============================================================================
-- END 026_season_admin_setup_api.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 027_competitive_matchdays.sql
-- ============================================================================
-- Phase 8H. Backend plans with the existing pure domain; SQL owns atomic commit.
begin;

alter table public.matchdays
  add column revision bigint not null default 0 check (revision>=0),
  add column results_revision bigint not null default 0 check (results_revision>=0);
alter table public.season_player_stats
  add column revived_after_wipe integer not null default 0 check (revived_after_wipe>=0);

create table public.matchday_snapshot_revisions (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  matchday_id uuid not null,
  revision integer not null check (revision>0),
  snapshot jsonb not null check (jsonb_typeof(snapshot)='object'),
  reason text not null,
  created_by_trainer_id uuid not null references public.trainers(id),
  created_at timestamptz not null default clock_timestamp(),
  unique(matchday_id,revision),
  foreign key(matchday_id,season_id) references public.matchdays(id,season_id)
);
alter table public.matchday_snapshot_revisions enable row level security;
revoke all on public.matchday_snapshot_revisions from public,anon,authenticated;
grant all on public.matchday_snapshot_revisions to service_role;
create trigger snapshot_revision_immutable before update on public.matchday_snapshot_revisions
  for each row execute function public.admin_setup_receipt_immutable();

alter table public.coin_transactions
  add column reward_matchday_id uuid,
  add column reward_revision integer,
  add foreign key(reward_matchday_id,season_id) references public.matchdays(id,season_id),
  add foreign key(reward_matchday_id,reward_revision) references public.matchday_snapshot_revisions(matchday_id,revision),
  add constraint reward_ledger_source_chk check (
    (reward_matchday_id is null and reward_revision is null) or
    (reward_matchday_id is not null and reward_revision is not null and reward_revision>0 and transaction_type in ('matchday_reward','compensation'))),
  add constraint uq_matchday_reward_revision unique(reward_matchday_id,season_player_id,reward_revision);
alter table public.purchases
  add column origin_matchday_id uuid,
  add column origin_snapshot_revision integer,
  add foreign key(origin_matchday_id,season_id) references public.matchdays(id,season_id),
  add foreign key(origin_matchday_id,origin_snapshot_revision) references public.matchday_snapshot_revisions(matchday_id,revision),
  add constraint uq_matchday_free_reward unique(origin_matchday_id,origin_snapshot_revision,season_player_id),
  drop constraint purchase_acquisition_chk,
  add constraint purchase_acquisition_chk check (
    (acquisition_type='paid' and unit_price>0 and origin_redemption_id is null
      and origin_matchday_id is null and origin_snapshot_revision is null)
    or (acquisition_type='reward' and unit_price=0 and quantity=1 and promotion_id is null
      and idempotency_key is null and balance_after is null and base_price_confirmed is null
      and ((origin_redemption_id is not null and origin_matchday_id is null and origin_snapshot_revision is null)
        or (origin_redemption_id is null and origin_matchday_id is not null and origin_snapshot_revision is not null and origin_snapshot_revision>0))));
create unique index uq_matchday_movement_player on public.matchday_movements(matchday_id,season_player_id);

create or replace function public.check_purchase_acquisition() returns trigger
language plpgsql security invoker set search_path='' as $$
declare v_item public.shop_items; v_origin public.redemptions;
begin
  select * into v_item from public.shop_items where id=new.shop_item_id for share;
  if new.acquisition_type='paid' and v_item.acquisition_mode<>'purchasable' then
    raise sqlstate 'PT409' using message='item_unavailable'; end if;
  if new.acquisition_type='reward' and new.origin_matchday_id is not null then
    if v_item.code<>'robar_pokemon' or v_item.acquisition_mode<>'purchasable' or not exists (
      select 1 from public.matchday_snapshot_revisions r join public.season_players p
      on p.id=(r.snapshot->>'last_b_player_id')::uuid
      where r.matchday_id=new.origin_matchday_id and r.revision=new.origin_snapshot_revision
      and r.season_id=new.season_id and p.id=new.season_player_id and p.trainer_id=new.trainer_id
    ) then raise sqlstate 'PT409' using message='invalid_reward_origin'; end if;
  elsif new.acquisition_type='reward' then
    select * into v_origin from public.redemptions where id=new.origin_redemption_id;
    if not found or v_item.code<>'robbery_shield_voucher' or v_item.acquisition_mode<>'reward_only'
      or v_origin.effect_code is distinct from 'steal' or v_origin.status<>'applied'
      or v_origin.season_id<>new.season_id or v_origin.trainer_id<>new.trainer_id
      or v_origin.season_player_id<>new.season_player_id or v_origin.gift_purchase_id is distinct from new.id then
      raise sqlstate 'PT409' using message='invalid_reward_origin'; end if;
  end if;
  return new;
end $$;

create function public.matchday_protect_snapshot() returns trigger
language plpgsql set search_path=pg_catalog,public as $$
begin
  if tg_op='UPDATE' and not exists(select 1 from public.matchday_snapshot_revisions where matchday_id=old.matchday_id) then
    return new; -- Historical pre-027 imports retain their existing contract.
  end if;
  if tg_op='UPDATE' and (new.matchday_id<>old.matchday_id or new.season_id<>old.season_id
     or new.config_version_id<>old.config_version_id or new.revision<>old.revision+1) then
    perform public.admin_setup_fail('stale_revision'); end if;
  if not exists(select 1 from public.matchday_snapshot_revisions r where r.matchday_id=new.matchday_id
      and r.revision=new.revision and r.season_id=new.season_id and r.snapshot=new.snapshot) then
    perform public.admin_setup_fail('invalid_results'); end if;
  return new;
end $$;
-- Apply the guard only to authoritative 8H snapshots, not older fixture imports.
create trigger authoritative_snapshot_guard before update on public.matchday_snapshots
  for each row execute function public.matchday_protect_snapshot();
revoke insert,update,delete on public.matchday_snapshots,public.matchday_movements,public.coin_transactions,
  public.matchday_snapshot_revisions from public,anon,authenticated;
do $$ declare t text; cols text; begin
  foreach t in array array['matchdays','matches','matchday_snapshots','matchday_movements',
    'coin_transactions','purchases','season_player_stats','matchday_snapshot_revisions'] loop
    select string_agg(quote_ident(attname),',') into cols from pg_attribute
      where attrelid=('public.'||t)::regclass and attnum>0 and not attisdropped;
    execute format('revoke insert (%s), update (%s) on public.%I from public,anon,authenticated',cols,cols,t);
  end loop;
end $$;

create function public.matchday_external_facts(sid uuid) returns text
language plpgsql set search_path=pg_catalog,public as $$
declare result jsonb='{}'; rows jsonb; t text; extra text;
begin
  -- Content hashes, not timestamps: a waiting transaction can carry an older now().
  foreach t in array array['purchases','coin_transactions','redemptions','team_locks','save_files',
    'pokemon_identity_revisions','pokemon_entity_flags','pokemon_flags','trainer_flags','season_player_stats',
    'penalties','cups','trial_cases'] loop
    extra=case t when 'purchases' then ' and origin_matchday_id is null'
      when 'coin_transactions' then ' and reward_matchday_id is null' else '' end;
    execute format('select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),''[]''::jsonb) from public.%I x where season_id=$1%s',t,extra)
      into rows using sid;
    result=result||jsonb_build_object(t,rows);
  end loop;
  return encode(sha256(convert_to(result::text,'UTF8')),'hex');
end $$;

create function public.matchday_validate(sid uuid,did uuid,complete boolean) returns void
language plpgsql set search_path=pg_catalog,public as $$
declare d public.matchdays; c public.season_config_versions; total integer; expected integer; v_code text; n integer;
begin
  select * into d from public.matchdays where id=did and season_id=sid;
  if not found then perform public.admin_setup_fail('matchday_not_found',404); end if;
  select * into c from public.season_config_versions where season_id=sid and effective_from_matchday<=d.number
    order by effective_from_matchday desc limit 1;
  if c.id is distinct from d.season_config_version_id or c.division_sizes is null or d.number>c.total_matchdays then
    perform public.admin_setup_fail('config_mismatch'); end if;
  if exists(select 1 from public.season_players where season_id=sid and status<>'active') then
    perform public.admin_setup_fail('invalid_roster'); end if;
  select count(*) into total from public.season_players where season_id=sid;
  if total<>(c.division_sizes->>'A')::integer+(c.division_sizes->>'B')::integer then
    perform public.admin_setup_fail('invalid_roster'); end if;
  if exists(select 1 from public.season_players p where p.season_id=sid and
    (select count(*) from public.division_memberships m where m.season_player_id=p.id
      and m.effective_from_matchday_number<=d.number and coalesce(m.effective_to_matchday_number,d.number)>=d.number)<>1) then
    perform public.admin_setup_fail('invalid_roster'); end if;
  expected=0;
  foreach v_code in array array['A','B'] loop
    select count(*) into n from public.division_memberships m join public.divisions v on v.id=m.division_id
      where m.season_id=sid and v.code=v_code and m.effective_from_matchday_number<=d.number
      and coalesce(m.effective_to_matchday_number,d.number)>=d.number;
    if n<>(c.division_sizes->>v_code)::integer then perform public.admin_setup_fail('invalid_roster'); end if;
    expected=expected+n*(n-1)/2;
  end loop;
  if (select count(*) from public.matches where matchday_id=did)<>expected or exists (
    select 1 from public.matches x where x.matchday_id=did and (x.status not in ('scheduled','completed')
    or (x.winner_id is null)<>(x.status='scheduled') or not exists (
      select 1 from public.division_memberships a join public.division_memberships b on a.division_id=b.division_id
      where a.season_player_id=x.player_a_id and b.season_player_id=x.player_b_id and a.division_id=x.division_id
      and a.effective_from_matchday_number<=d.number and coalesce(a.effective_to_matchday_number,d.number)>=d.number
      and b.effective_from_matchday_number<=d.number and coalesce(b.effective_to_matchday_number,d.number)>=d.number))) then
    perform public.admin_setup_fail('invalid_results'); end if;
  if complete and exists(select 1 from public.matches where matchday_id=did and winner_id is null) then
    perform public.admin_setup_fail('results_incomplete'); end if;
end $$;

create function public.matchday_lock(op text,r jsonb) returns jsonb
language plpgsql set search_path=pg_catalog,public as $$
declare cached jsonb; sid uuid=(r->>'season_id')::uuid; did uuid=(r->>'resource_id')::uuid;
  d public.matchdays; s public.seasons; snap public.matchday_snapshots; nextday public.matchdays; change jsonb;
begin
  cached=public.admin_setup_begin('matchday_'||op,r);
  if cached is not null then return cached; end if;
  select * into s from public.seasons where id=sid;
  if s.status<>'active' then perform public.admin_setup_fail('season_not_active'); end if;
  select * into d from public.matchdays where id=did and season_id=sid for update;
  if not found then perform public.admin_setup_fail('matchday_not_found',404); end if;
  perform 1 from public.matches where matchday_id=did order by id for update;
  perform 1 from public.season_config_versions where season_id=sid order by id for share;
  if op in ('close','correct') then
    perform 1 from public.shop_items order by id for share;
    perform 1 from public.shop_promotions where season_id=sid order by id for update;
  end if;
  if op='correct' then
    select * into snap from public.matchday_snapshots where matchday_id=did;
    if d.status<>'closed' or snap.id is null or not (snap.snapshot ? 'external_facts')
      or exists(select 1 from public.matchday_snapshots x join public.matchdays md on md.id=x.matchday_id
        where x.season_id=sid and md.number>d.number)
      or snap.snapshot->>'external_facts' is distinct from public.matchday_external_facts(sid) then
      perform public.admin_setup_fail('correction_window_closed'); end if;
    if snap.revision<>(r->'body'->>'expected_snapshot_revision')::integer then
      perform public.admin_setup_fail('stale_revision'); end if;
    if jsonb_typeof(r->'body'->'results') is distinct from 'array' or jsonb_array_length(r->'body'->'results')=0
      or (select count(distinct value->>'match_id') from jsonb_array_elements(r->'body'->'results'))<>jsonb_array_length(r->'body'->'results') then
      perform public.admin_setup_fail('invalid_results'); end if;
    for change in select value from jsonb_array_elements(r->'body'->'results') loop
      if not exists(select 1 from public.matches m where m.id=(change->>'match_id')::uuid and m.matchday_id=did
        and (change->>'winner_season_player_id')::uuid in (m.player_a_id,m.player_b_id)) then
        perform public.admin_setup_fail('invalid_results'); end if;
    end loop;
    -- No cross-competition cascade: even a pre-existing cup may depend on standings.
    if exists(select 1 from public.cups where season_id=sid)
      or exists(select 1 from public.redemptions where season_id=sid and physical_effect_status='pending') then
      perform public.admin_setup_fail('correction_window_closed'); end if;
    if s.current_matchday_id<>did then
      select * into nextday from public.matchdays where id=s.current_matchday_id for update;
      if nextday.number<>d.number+1 or nextday.status<>'scheduled'
        or exists(select 1 from public.matches where matchday_id=nextday.id and winner_id is not null)
        or exists(select 1 from public.team_locks where matchday_id=nextday.id)
        or exists(select 1 from public.matchday_movements where matchday_id=nextday.id)
        or exists(select 1 from public.penalties where matchday_id=nextday.id) then
        perform public.admin_setup_fail('correction_window_closed'); end if;
    end if;
    if exists(select 1 from public.purchases p where p.origin_matchday_id=did and
      (p.status not in ('pending','cancelled') or exists(select 1 from public.redemptions where purchase_id=p.id))) then
      perform public.admin_setup_fail('correction_window_closed'); end if;
  else
    if s.current_matchday_id is distinct from did then perform public.admin_setup_fail('matchday_not_current'); end if;
    if op='open' then
      if d.status<>'scheduled' then perform public.admin_setup_fail('matchday_not_scheduled'); end if;
    elsif d.status<>'open' then perform public.admin_setup_fail(case when d.status='closed' then 'already_closed' else 'matchday_not_open' end); end if;
    if (r->'body' ? 'expected_revision' and (r->'body'->>'expected_revision')::bigint<>d.revision)
      or (r->'body' ? 'expected_results_revision' and (r->'body'->>'expected_results_revision')::bigint<>d.results_revision) then
      perform public.admin_setup_fail('stale_revision'); end if;
    perform public.matchday_validate(sid,did,op='close');
  end if;
  return null;
end $$;

create function public.matchday_context(op text,r jsonb) returns jsonb
language plpgsql set search_path=pg_catalog,public as $$
declare sid uuid=(r->>'season_id')::uuid; did uuid=(r->>'resource_id')::uuid;
  d public.matchdays; c public.season_config_versions; inputs jsonb; players jsonb; matches jsonb; result jsonb;
begin
  select * into d from public.matchdays where id=did;
  select * into c from public.season_config_versions where id=d.season_config_version_id;
  if (c.rules_json->>'last_b_gets_steal')::boolean and not exists (
    select 1 from public.shop_items where code='robar_pokemon' and acquisition_mode='purchasable'
  ) then perform public.admin_setup_fail('reward_item_unavailable'); end if;
  if op='correct' then
    select snapshot->'inputs' into inputs from public.matchday_snapshots where matchday_id=did;
  else
    if exists(select 1 from public.season_players p where p.season_id=sid and p.current_save_file_id is not null
      and not exists(select 1 from public.pokemon_identity_revisions i where i.save_file_id=p.current_save_file_id)) then
      perform public.admin_setup_fail('ranking_inputs_unavailable'); end if;
    select jsonb_agg(jsonb_build_object('id',p.id,'trainer_id',p.trainer_id,'ranking_key',t.slug,'division',v.code,
      'dead_count',(select count(*) from public.pokemon_observations o where o.save_file_id=p.current_save_file_id and o.source='box' and o.box_number=8)
        +greatest((select count(*) from public.redemptions e where e.season_id=sid and e.trainer_id=p.trainer_id and e.effect_code='revive' and e.status='applied'),
          (select count(*) from public.purchases u join public.shop_items i on i.id=u.shop_item_id where u.season_player_id=p.id and u.status='used' and i.code='revivir_pokemon'))
        +2*st.revived_after_wipe,
      'points_reduction',coalesce((select sum(greatest(amount,0)) from public.penalties pe where pe.season_id=sid and pe.trainer_id=p.trainer_id
        and pe.penalty_type='points_reduction' and (pe.matchday_id is null or pe.matchday_id=did)
        and (pe.trial_case_id is null or exists(select 1 from public.trial_cases tc where tc.id=pe.trial_case_id and tc.status='resolved'
          and tc.accused_trainer_id=p.trainer_id and (tc.season_id is null or tc.season_id=sid)))),0),
      'coins_reduction',coalesce((select sum(greatest(amount,0)) from public.penalties pe where pe.season_id=sid and pe.trainer_id=p.trainer_id
        and pe.penalty_type='coins_reduction' and (pe.matchday_id is null or pe.matchday_id=did)
        and (pe.trial_case_id is null or exists(select 1 from public.trial_cases tc where tc.id=pe.trial_case_id and tc.status='resolved'
          and tc.accused_trainer_id=p.trainer_id and (tc.season_id is null or tc.season_id=sid)))) ,0)) order by p.id) into players
      from public.season_players p join public.trainers t on t.id=p.trainer_id
      join public.season_player_stats st on st.season_player_id=p.id
      join public.division_memberships m on m.season_player_id=p.id and m.effective_from_matchday_number<=d.number
        and coalesce(m.effective_to_matchday_number,d.number)>=d.number
      join public.divisions v on v.id=m.division_id where p.season_id=sid;
    select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'player_a_id',x.player_a_id,'player_b_id',x.player_b_id,
      'winner_id',x.winner_id,'division',v.code) order by x.id),'[]'::jsonb) into matches
      from public.matches x join public.divisions v on v.id=x.division_id where x.matchday_id=did;
    inputs=jsonb_build_object('season_id',sid,'day_id',did,'number',d.number,'results_revision',d.results_revision,
      'config',jsonb_build_object('id',c.id,'name',c.name,'effective_from_matchday',c.effective_from_matchday,
        'total_matchdays',c.total_matchdays,'division_sizes',c.division_sizes,'promotion_relegation_count',c.promotion_relegation_count,
        'scoring_json',c.scoring_json,'coin_rewards_json',c.coin_rewards_json,'rules_json',c.rules_json),
      'players',players,'matches',matches);
  end if;
  result=jsonb_build_object('inputs',inputs,'external_facts',public.matchday_external_facts(sid),
    'snapshot_revision',coalesce((select revision from public.matchday_snapshots where matchday_id=did),0),
    'next_config',(select to_jsonb(x) from public.season_config_versions x where x.season_id=sid and x.effective_from_matchday<=d.number+1
      order by x.effective_from_matchday desc limit 1),
    'existing_next_promotions',exists(select 1 from public.shop_promotions p join public.matchdays md on md.id=p.matchday_id
      where p.season_id=sid and md.number=d.number+1),
    'catalog',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'code',i.code,'name',i.name,'category',i.category,'base_price',i.base_price,'enabled',i.enabled) order by i.id),'[]'::jsonb)
      from public.shop_items i where i.acquisition_mode='purchasable'),
    'purchase_history',(select coalesce(jsonb_agg(jsonb_build_object('name',i.name,'number',coalesce(md.number,0),'quantity',p.quantity) order by p.id),'[]'::jsonb)
      from public.purchases p join public.shop_items i on i.id=p.shop_item_id left join public.matchdays md
      on md.id=coalesce((p.metadata#>>'{normal_purchase,matchday_id}')::uuid,(p.metadata#>>'{promotional_purchase,matchday_id}')::uuid,p.origin_matchday_id)
      where p.season_id=sid and p.status not in ('cancelled','refunded')),
    'promotion_history',(select coalesce(jsonb_agg(jsonb_build_object('item',i.name,'jornada',md.number) order by p.id),'[]'::jsonb)
      from public.shop_promotions p join public.shop_items i on i.id=p.shop_item_id join public.matchdays md on md.id=p.matchday_id where p.season_id=sid));
  return result;
end $$;

create function public.api_admin_matchday_context(p_request jsonb) returns jsonb
language plpgsql set search_path=pg_catalog,public as $$
declare op text=p_request->>'operation'; r jsonb=p_request->'request'; cached jsonb; ctx jsonb;
begin
  if op not in ('close','correct') then perform public.admin_setup_fail('invalid_request',422); end if;
  cached=public.matchday_lock(op,r);
  if cached is not null then return jsonb_build_object('receipt',cached); end if;
  ctx=public.matchday_context(op,r);
  return jsonb_build_object('context',ctx,'input_hash',encode(sha256(convert_to(ctx::text,'UTF8')),'hex'));
end $$;

create function public.matchday_results(did uuid,changes jsonb,correcting boolean default false) returns void
language plpgsql set search_path=pg_catalog,public as $$
declare x jsonb; m public.matches; wid uuid;
begin
  if jsonb_typeof(changes) is distinct from 'array' or jsonb_array_length(changes)=0
    or (select count(distinct value->>'match_id') from jsonb_array_elements(changes))<>jsonb_array_length(changes) then
    perform public.admin_setup_fail('invalid_results'); end if;
  for x in select value from jsonb_array_elements(changes) loop
    select * into m from public.matches where id=(x->>'match_id')::uuid and matchday_id=did;
    wid=(x->>'winner_season_player_id')::uuid;
    if not found or (correcting and wid is null) or (wid is not null and wid not in (m.player_a_id,m.player_b_id)) then
      perform public.admin_setup_fail('invalid_results'); end if;
    update public.matches set winner_id=wid,status=case when wid is null then 'scheduled' else 'completed' end where id=m.id;
  end loop;
end $$;

create function public.matchday_commit_close(op text,r jsonb,ctx jsonb,plan jsonb) returns void
language plpgsql set search_path=pg_catalog,public as $$
declare sid uuid=(r->>'season_id')::uuid; did uuid=(r->>'resource_id')::uuid; actor uuid=(r->>'actor_trainer_id')::uuid;
  d public.matchdays; cfg public.season_config_versions; nxtcfg public.season_config_versions;
  old public.matchday_snapshots; v_snapshot jsonb; rev integer; final boolean; nextid uuid; divisionid uuid;
  pid uuid; tid uuid; gift uuid; giftplayer uuid; oldgift public.purchases; row jsonb; divcode text;
  v_amount integer; prior integer; stamp timestamptz=clock_timestamp();
begin
  select * into d from public.matchdays where id=did;
  select * into cfg from public.season_config_versions where id=d.season_config_version_id;
  select * into old from public.matchday_snapshots where matchday_id=did;
  rev=coalesce(old.revision,0)+1; final=d.number=cfg.total_matchdays;
  if op='correct' then
    perform public.matchday_results(did,r->'body'->'results',true);
    perform public.matchday_validate(sid,did,true);
  end if;
  if jsonb_typeof(plan->'standings') is distinct from 'array' or jsonb_array_length(plan->'standings')<>
    (select count(*) from public.season_players where season_id=sid)
    or (select count(distinct value->>'trainer_id') from jsonb_array_elements(plan->'standings'))<>jsonb_array_length(plan->'standings') then
    perform public.admin_setup_fail('invalid_results'); end if;
  for row in select value from jsonb_array_elements(plan->'standings') loop
    if not exists(select 1 from public.season_players where id=(row->>'trainer_id')::uuid and season_id=sid)
      or (row->>'coins_awarded')::integer is distinct from (cfg.coin_rewards_json->>(row->>'position'))::integer
      or (row->>'points_awarded')::integer is distinct from (cfg.scoring_json->>(row->>'position'))::integer then
      perform public.admin_setup_fail('invalid_results'); end if;
  end loop;
  giftplayer=(plan->>'last_b_player_id')::uuid;
  if (cfg.rules_json->>'last_b_gets_steal')::boolean then
    select id into gift from public.shop_items where code='robar_pokemon' and acquisition_mode='purchasable' for share;
    if gift is null or giftplayer is null then perform public.admin_setup_fail('reward_item_unavailable'); end if;
  elsif giftplayer is not null then perform public.admin_setup_fail('invalid_results'); end if;
  v_snapshot=jsonb_build_object('schema_version',2,'revision',rev,'closed_at',stamp,'inputs',
    jsonb_set(ctx->'inputs','{matches}',plan->'matches'),'standings',plan->'standings',
    'new_divisions',plan->'new_divisions','last_b_player_id',giftplayer,'external_facts',ctx->'external_facts',
    'final',final,'reason',case when op='correct' then r->'body'->>'reason' else 'close' end);
  insert into public.matchday_snapshot_revisions(season_id,matchday_id,revision,snapshot,reason,created_by_trainer_id)
    values(sid,did,rev,v_snapshot,v_snapshot->>'reason',actor);
  if old.id is null then
    insert into public.matchday_snapshots(season_id,matchday_id,config_version_id,revision,snapshot_schema_version,closed_at,snapshot,created_by_trainer_id)
      values(sid,did,cfg.id,rev,2,stamp,v_snapshot,actor);
  else
    update public.matchday_snapshots set revision=rev,snapshot=v_snapshot,closed_at=stamp,created_by_trainer_id=actor where id=old.id;
  end if;
  for row in select value from jsonb_array_elements(plan->'standings') loop
    pid=(row->>'trainer_id')::uuid;
    select trainer_id into tid from public.season_players where id=pid;
    prior=0;
    if old.id is not null then select (x->>'coins_awarded')::integer into prior from jsonb_array_elements(old.snapshot->'standings') x where x->>'trainer_id'=pid::text; end if;
    v_amount=(row->>'coins_awarded')::integer-coalesce(prior,0);
    if v_amount<0 and (select coalesce(sum(amount),0) from public.coin_transactions where season_player_id=pid)+v_amount<0 then
      perform public.admin_setup_fail('correction_window_closed'); end if;
    if v_amount<>0 then
      insert into public.coin_transactions(season_id,trainer_id,season_player_id,amount,transaction_type,reference_type,reference_id,
        reward_matchday_id,reward_revision,created_by_trainer_id,metadata)
        values(sid,tid,pid,v_amount,case when op='close' then 'matchday_reward' else 'compensation' end,
          'matchday_snapshot_revision',(select id from public.matchday_snapshot_revisions where matchday_id=did and revision=rev),
          did,rev,actor,jsonb_build_object('reason',v_snapshot->>'reason','previous_revision',rev-1));
    end if;
  end loop;
  select * into oldgift from public.purchases where origin_matchday_id=did and status='pending' order by origin_snapshot_revision desc limit 1 for update;
  if oldgift.id is not null and oldgift.season_player_id is distinct from giftplayer then
    update public.purchases set status='cancelled',metadata=metadata||jsonb_build_object('cancelled_by_revision',rev,'reason',v_snapshot->>'reason') where id=oldgift.id;
  end if;
  if giftplayer is not null and (oldgift.id is null or oldgift.season_player_id<>giftplayer) then
    select trainer_id into tid from public.season_players where id=giftplayer;
    insert into public.purchases(season_id,trainer_id,season_player_id,shop_item_id,quantity,unit_price,status,
      acquisition_type,origin_matchday_id,origin_snapshot_revision)
      values(sid,tid,giftplayer,gift,1,0,'pending','reward',did,rev);
  end if;
  if not final then
    select * into nxtcfg from public.season_config_versions where season_id=sid and effective_from_matchday<=d.number+1
      order by effective_from_matchday desc limit 1;
    if nxtcfg.total_matchdays<d.number+1 or nxtcfg.division_sizes<>cfg.division_sizes then
      perform public.admin_setup_fail('config_mismatch'); end if;
    select id into nextid from public.matchdays where season_id=sid and number=d.number+1;
    if op='close' and nextid is not null then perform public.admin_setup_fail('dependent_data_exists'); end if;
    if op='correct' then
      delete from public.matchday_movements where matchday_id=did;
      delete from public.matches where matchday_id=nextid;
      delete from public.division_memberships where source_matchday_id=did;
    end if;
    update public.division_memberships set effective_to_matchday_number=d.number where season_id=sid
      and effective_from_matchday_number<=d.number and coalesce(effective_to_matchday_number,d.number)>=d.number;
    foreach divcode in array array['A','B'] loop
      select id into divisionid from public.divisions where season_id=sid and code=divcode;
      for pid in select value::uuid from jsonb_array_elements_text(plan->'new_divisions'->divcode) loop
        insert into public.matchday_movements(season_id,matchday_id,season_player_id,from_division_id,to_division_id,movement_type,metadata)
          select sid,did,pid,m.division_id,divisionid,case when m.division_id=divisionid then 'stay' when divcode='A' then 'promotion' else 'relegation' end,
            jsonb_build_object('snapshot_revision',rev) from public.division_memberships m where m.season_player_id=pid
            and m.effective_from_matchday_number<=d.number and m.effective_to_matchday_number=d.number;
        insert into public.division_memberships(season_id,season_player_id,division_id,effective_from_matchday_number,source_matchday_id,reason)
          select sid,pid,divisionid,d.number+1,did,case when movement_type='stay' then 'initial' else movement_type end
            from public.matchday_movements where matchday_id=did and season_player_id=pid;
      end loop;
    end loop;
    if nextid is null then
      insert into public.matchdays(season_id,number,season_config_version_id) values(sid,d.number+1,nxtcfg.id) returning id into nextid;
    end if;
    insert into public.matches(season_id,matchday_id,division_id,player_a_id,player_b_id)
      select sid,nextid,a.division_id,a.season_player_id,b.season_player_id from public.division_memberships a
      join public.division_memberships b on a.division_id=b.division_id and a.season_player_id<b.season_player_id
      where a.season_id=sid and a.effective_from_matchday_number=d.number+1 and b.effective_from_matchday_number=d.number+1;
    perform public.matchday_validate(sid,nextid,false);
    if op='close' then
      for row in select value from jsonb_array_elements(plan->'promotions') loop
        insert into public.shop_promotions(season_id,matchday_id,shop_item_id,promotion_type,status,base_price,effective_price,stock_total,
          announced_at,activates_at,dedupe_key,metadata)
          values(sid,nextid,(row->>'shop_item_id')::uuid,row->>'promotion_type','pending',(row->>'base_price')::integer,
            (row->>'effective_price')::integer,(row->>'stock_total')::integer,stamp,stamp+interval '24 hours',
            'matchday:'||did::text||':'||(row->>'shop_item_id'),jsonb_build_object('source_matchday_id',did));
      end loop;
    end if;
    update public.seasons set current_matchday_id=nextid where id=sid;
  end if;
  if op='close' then
    update public.shop_promotions set status='ended',ends_at=stamp where season_id=sid and status in ('pending','active','exhausted')
      and matchday_id in (select id from public.matchdays where season_id=sid and number<=d.number);
  end if;
  update public.matchdays set status='closed',closed_at=coalesce(closed_at,stamp),revision=revision+1,results_revision=results_revision+1 where id=did;
end $$;

create function public.api_admin_matchday(p_request jsonb) returns jsonb
language plpgsql set search_path=pg_catalog,public as $$
declare op text=p_request->>'operation'; r jsonb=p_request->'request'; cached jsonb; ctx jsonb; result jsonb;
  sid uuid=(r->>'season_id')::uuid; did uuid=(r->>'resource_id')::uuid; d public.matchdays; oid uuid=gen_random_uuid(); eid uuid=gen_random_uuid();
begin
  if op='state' then
    perform public.admin_setup_principal((r->>'actor_trainer_id')::uuid);
    perform 1 from public.seasons where id=sid for share;
  else
    if op not in ('open','results','cancel','close','correct') then perform public.admin_setup_fail('invalid_request',422); end if;
    cached=public.matchday_lock(op,r); if cached is not null then return cached; end if;
  end if;
  select * into d from public.matchdays where id=did and season_id=sid;
  if not found then perform public.admin_setup_fail('matchday_not_found',404); end if;
  if op='open' then
    update public.matchdays set status='open',opened_at=clock_timestamp(),revision=revision+1,results_revision=results_revision+1 where id=did;
  elsif op='results' then
    perform public.matchday_results(did,r->'body'->'results');
    update public.matchdays set revision=revision+1,results_revision=results_revision+1 where id=did;
  elsif op='cancel' then
    if exists(select 1 from public.matches where matchday_id=did and winner_id is not null)
      or exists(select 1 from public.matchday_snapshots where matchday_id=did)
      or exists(select 1 from public.matchday_movements where matchday_id=did) then
      perform public.admin_setup_fail('dependent_data_exists'); end if;
    update public.matchdays set status='scheduled',opened_at=null,revision=revision+1,results_revision=results_revision+1 where id=did;
  elsif op in ('close','correct') then
    ctx=public.matchday_context(op,r);
    if p_request->>'input_hash' is distinct from encode(sha256(convert_to(ctx::text,'UTF8')),'hex') then
      perform public.admin_setup_fail('stale_inputs'); end if;
    perform public.matchday_commit_close(op,r,ctx,p_request->'plan');
  end if;
  select jsonb_build_object('season_id',sid,'matchday_id',did,'state',x.status,'revision',x.revision,'results_revision',x.results_revision,
    'snapshot_revision',coalesce((select revision from public.matchday_snapshots where matchday_id=did),0),
    'current_matchday_id',s.current_matchday_id) into result from public.matchdays x join public.seasons s on s.id=x.season_id where x.id=did;
  if op='state' then
    return result||jsonb_build_object('matches',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'player_a_id',player_a_id,
      'player_b_id',player_b_id,'winner_id',winner_id) order by id),'[]'::jsonb) from public.matches where matchday_id=did));
  end if;
  insert into public.activity_events(id,season_id,type,actor_trainer_id,visibility,dedupe_key,payload)
    values(eid,sid,'MATCHDAY_ADMIN_'||upper(op),(r->>'actor_trainer_id')::uuid,'admin','matchday-admin:'||oid::text,
      result||jsonb_build_object('reason',r->'body'->>'reason','operation_id',oid));
  result=result||jsonb_build_object('operation_id',oid,'event_id',eid,'replayed',false);
  insert into public.admin_operation_receipts(id,actor_trainer_id,season_id,operation_scope,idempotency_key,request_hash,response_json)
    values(oid,(r->>'actor_trainer_id')::uuid,sid,public.admin_setup_scope('matchday_'||op,r),r->>'idempotency_key',
      encode(sha256(convert_to(r::text,'UTF8')),'hex'),result);
  return result;
end $$;

do $$ declare f regprocedure; begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and (p.proname like 'matchday_%' or p.proname like 'api_admin_matchday%') loop
    execute format('revoke all on function %s from public,anon,authenticated',f);
    execute format('grant execute on function %s to service_role',f);
  end loop;
end $$;
notify pgrst,'reload schema';
commit;
-- ============================================================================
-- END 027_competitive_matchdays.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 028_participant_status_admin.sql
-- ============================================================================
-- Phase 8I: permanent competitive withdrawal, never account disabling or history deletion.
begin;

alter table public.season_players
  add column status_effective_matchday_number integer,
  add column status_reason text,
  add column status_changed_by_trainer_id uuid references public.trainers(id),
  add constraint participant_status_evidence_chk check (
    (status_effective_matchday_number is null and status_reason is null and status_changed_by_trainer_id is null)
    or (status<>'active' and status_effective_matchday_number>0 and status_effective_matchday_number is not null
      and status_reason is not null and length(btrim(status_reason)) between 1 and 500
      and status_changed_by_trainer_id is not null and left_at is not null));

-- Original assignment ranges remain evidence, including an assignment cancelled
-- before its first competitive round. Intersection with this exclusive boundary
-- expresses an empty range without deleting history or inventing round zero.
alter table public.division_memberships
  add column eligibility_ends_before_matchday_number integer
    check (eligibility_ends_before_matchday_number>0);

-- Preserve 018 safe-by-shape public projections; expose only the new round
-- boundaries, not admin reasons/actors or any private source data.
create or replace view public.public_season_players
with (security_invoker=false,security_barrier=true) as
select id,season_id,trainer_id,status,seed_order,joined_at,left_at,created_at,updated_at,
  status_effective_matchday_number from public.season_players;
create or replace view public.public_division_memberships
with (security_invoker=false,security_barrier=true) as
select id,season_id,season_player_id,division_id,effective_from_matchday_number,effective_to_matchday_number,
  source_matchday_id,reason,created_at,eligibility_ends_before_matchday_number from public.division_memberships;

create function public.participant_memberships_at(sid uuid, round_number integer)
returns setof public.division_memberships language sql stable
security invoker set search_path=pg_catalog,public as $$
  select m.* from public.division_memberships m join public.season_players p on p.id=m.season_player_id
  where m.season_id=sid and m.effective_from_matchday_number<=round_number
    and coalesce(m.effective_to_matchday_number,round_number)>=round_number
    and (m.eligibility_ends_before_matchday_number is null or round_number<m.eligibility_ends_before_matchday_number)
    and (p.status='active' or round_number<p.status_effective_matchday_number)
$$;

create function public.participant_status_immutable() returns trigger
language plpgsql security invoker set search_path=pg_catalog,public as $$
begin
  if old.status_effective_matchday_number is not null and
    (new.status,new.status_effective_matchday_number,new.status_reason,new.status_changed_by_trainer_id,new.left_at)
    is distinct from (old.status,old.status_effective_matchday_number,old.status_reason,old.status_changed_by_trainer_id,old.left_at) then
    perform public.admin_setup_fail('participant_already_inactive');
  end if;
  return new;
end $$;
create trigger participant_status_evidence_immutable before update on public.season_players
  for each row execute function public.participant_status_immutable();

create function public.api_admin_participant_status(p_request jsonb) returns jsonb
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare r jsonb=p_request; b jsonb=r->'body'; sid uuid=(r->>'season_id')::uuid;
  pid uuid=(r->>'resource_id')::uuid; actor uuid=(r->>'actor_trainer_id')::uuid;
  destination text; cached jsonb; s public.seasons; p public.season_players; d public.matchdays;
  cycle public.robbery_cycles; active_ids uuid[]; result jsonb; stamp timestamptz;
  oid uuid=gen_random_uuid(); eid uuid=gen_random_uuid();
begin
  destination=case r->>'operation' when 'retire' then 'retired' when 'abandon' then 'abandoned'
    when 'disqualify' then 'disqualified' end;
  if destination is null or b is null or jsonb_typeof(b)<>'object'
    or b-array['reason','expected_roster_revision']<>'{}'::jsonb
    or jsonb_typeof(b->'reason') is distinct from 'string' or length(btrim(b->>'reason')) not between 1 and 500
    or jsonb_typeof(b->'expected_roster_revision') is distinct from 'number'
    or (b->>'expected_roster_revision') !~ '^[0-9]+$' then
    perform public.admin_setup_fail('invalid_request',422); end if;
  cached=public.admin_setup_begin('participant_status',r);
  if cached is not null then return cached; end if;
  select * into s from public.seasons where id=sid;
  if s.status<>'active' then perform public.admin_setup_fail('season_not_active'); end if;
  select * into p from public.season_players where id=pid and season_id=sid;
  if not found then perform public.admin_setup_fail('participant_not_found',404); end if;
  if p.status<>'active' then perform public.admin_setup_fail('participant_already_inactive'); end if;
  perform public.admin_setup_cas(sid,b);
  select * into d from public.matchdays where id=s.current_matchday_id and season_id=sid for update;
  if d.status='open' then perform public.admin_setup_fail('round_open'); end if;
  if d.id is null or d.status<>'scheduled' then perform public.admin_setup_fail('matchday_not_scheduled'); end if;
  perform 1 from public.division_memberships where season_id=sid order by id for update;
  perform 1 from public.matches where matchday_id=d.id order by id for update;
  if exists(select 1 from public.team_locks where matchday_id=d.id and season_player_id=pid) then
    perform public.admin_setup_fail('participant_has_current_team_lock'); end if;
  if exists(select 1 from public.matches where matchday_id=d.id and (winner_id is not null or status<>'scheduled' or result_code<>''))
    or exists(select 1 from public.matchday_snapshots where matchday_id=d.id)
    or exists(select 1 from public.matchday_snapshot_revisions where matchday_id=d.id)
    or exists(select 1 from public.matchday_movements where matchday_id=d.id)
    or exists(select 1 from public.coin_transactions where reward_matchday_id=d.id
      or (transaction_type='matchday_reward' and reference_id=d.id))
    or exists(select 1 from public.purchases where origin_matchday_id=d.id)
    or exists(select 1 from public.penalties where matchday_id=d.id)
    or exists(select 1 from public.trial_cases where matchday_id=d.id)
    or exists(select 1 from public.matchdays where season_id=sid and number>d.number) then
    perform public.admin_setup_fail('dependent_data_exists'); end if;
  -- Unknown team membership cannot be safely inferred from arbitrary Cup JSON.
  if exists(select 1 from public.cups c join public.cup_participants cp on cp.cup_id=c.id
      where c.season_id=sid and c.status in ('draft','active')
      and (cp.trainer_id=p.trainer_id or cp.trainer_id is null)) then
    perform public.admin_setup_fail('ongoing_competition_dependency'); end if;
  perform public.matchday_validate(sid,d.id,false);
  stamp=clock_timestamp();
  update public.season_players set status=destination,left_at=stamp,status_reason=btrim(b->>'reason'),
    status_effective_matchday_number=d.number,status_changed_by_trainer_id=actor where id=pid;
  update public.division_memberships set eligibility_ends_before_matchday_number=d.number
    where season_player_id=pid and coalesce(effective_to_matchday_number,d.number)>=d.number;
  -- Only remove the departing player's unpublished pairs. Other match IDs and
  -- every remaining player's day/save Team Lock stay exactly the same.
  delete from public.matches where matchday_id=d.id and pid in (player_a_id,player_b_id);
  perform public.matchday_validate(sid,d.id,false);
  update public.matchdays set revision=revision+1,results_revision=results_revision+1 where id=d.id;
  update public.trainer_flags set flag_value=false,payload='{}'
    where season_id=sid and trainer_id=p.trainer_id and flag_type='robbed';
  select * into cycle from public.robbery_cycles where season_id=sid for update;
  select coalesce(array_agg(trainer_id order by id),array[]::uuid[]) into active_ids
    from public.season_players where season_id=sid and status='active';
  -- Same durable-cycle completeness and watermark rule as 025. No empty-set
  -- rollover: with no active participants there is no next eligible robbery.
  if cycle.season_id is not null and cardinality(active_ids)>0 and not exists (
    select 1 from unnest(active_ids) t(id) where not exists (
      select 1 from public.redemptions e where e.season_id=sid
        and e.robbery_cycle_number=cycle.cycle_number and e.target_owner_trainer_id=t.id)) then
    update public.robbery_cycles set cycle_number=cycle_number+1,history_watermark_id=last_redemption_id where season_id=sid;
    update public.trainer_flags set flag_value=false,payload='{}'
      where season_id=sid and flag_type='robbed' and trainer_id=any(active_ids);
  end if;
  update public.season_admin_state set roster_revision=roster_revision+1,setup_revision=setup_revision+1 where season_id=sid;
  select jsonb_build_object('operation_id',oid,'event_id',eid,'season_id',sid,'participant_id',pid,
    'old_status','active','new_status',destination,'reason',btrim(b->>'reason'),'effective_matchday_id',d.id,
    'effective_matchday_number',d.number,'actor_trainer_id',actor,'changed_at',stamp,
    'roster_revision',a.roster_revision,'setup_revision',a.setup_revision,'replayed',false) into result
    from public.season_admin_state a where season_id=sid;
  insert into public.activity_events(id,season_id,type,actor_trainer_id,visibility,dedupe_key,payload)
    values(eid,sid,'PARTICIPANT_STATUS_CHANGED',actor,'admin','participant-status:'||oid::text,result);
  insert into public.admin_operation_receipts(id,actor_trainer_id,season_id,operation_scope,idempotency_key,request_hash,response_json)
    values(oid,actor,sid,public.admin_setup_scope('participant_status',r),r->>'idempotency_key',
      encode(sha256(convert_to(r::text,'UTF8')),'hex'),result);
  return result;
end $$;

-- 027 replacements below only adapt eligibility, empty divisions and correction
-- invalidation. Existing rewards, movements and receipts keep their contract.

create or replace function public.matchday_external_facts(sid uuid) returns text
language plpgsql set search_path=pg_catalog,public as $$
declare result jsonb='{}'; rows jsonb; t text; extra text;
begin
  -- Content hashes, not timestamps: a waiting transaction can carry an older now().
  foreach t in array array['purchases','coin_transactions','redemptions','team_locks','save_files',
    'pokemon_identity_revisions','pokemon_entity_flags','pokemon_flags','trainer_flags','season_player_stats',
    'penalties','cups','trial_cases'] loop
    extra=case t when 'purchases' then ' and origin_matchday_id is null'
      when 'coin_transactions' then ' and reward_matchday_id is null' else '' end;
    execute format('select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),''[]''::jsonb) from public.%I x where season_id=$1%s',t,extra)
      into rows using sid;
    result=result||jsonb_build_object(t,rows);
  end loop;
  if exists(select 1 from public.season_players where season_id=sid and status_effective_matchday_number is not null) then
    result=result||jsonb_build_object('participant_boundaries',
      (select jsonb_agg(jsonb_build_object('id',id,'status',status,'effective',status_effective_matchday_number) order by id)
       from public.season_players where season_id=sid));
  end if;
  return encode(sha256(convert_to(result::text,'UTF8')),'hex');
end $$;

create or replace function public.matchday_validate(sid uuid,did uuid,complete boolean) returns void
language plpgsql set search_path=pg_catalog,public as $$
declare d public.matchdays; c public.season_config_versions; total integer; expected integer; v_code text; n integer;
begin
  select * into d from public.matchdays where id=did and season_id=sid;
  if not found then perform public.admin_setup_fail('matchday_not_found',404); end if;
  select * into c from public.season_config_versions where season_id=sid and effective_from_matchday<=d.number
    order by effective_from_matchday desc limit 1;
  if c.id is distinct from d.season_config_version_id or c.division_sizes is null or d.number>c.total_matchdays then
    perform public.admin_setup_fail('config_mismatch'); end if;
  if exists(select 1 from public.season_players where season_id=sid and status<>'active' and status_effective_matchday_number is null) then
    perform public.admin_setup_fail('invalid_roster'); end if;
  select count(*) into total from public.season_players where season_id=sid;
  if total<>(c.division_sizes->>'A')::integer+(c.division_sizes->>'B')::integer then
    perform public.admin_setup_fail('invalid_roster'); end if;
  if exists(select 1 from public.season_players p where p.season_id=sid and (p.status='active' or d.number<p.status_effective_matchday_number) and
    (select count(*) from public.participant_memberships_at(sid,d.number) m where m.season_player_id=p.id
      and m.effective_from_matchday_number<=d.number and coalesce(m.effective_to_matchday_number,d.number)>=d.number)<>1) then
    perform public.admin_setup_fail('invalid_roster'); end if;
  expected=0;
  foreach v_code in array array['A','B'] loop
    select count(*) into n from public.participant_memberships_at(sid,d.number) m join public.divisions v on v.id=m.division_id
      where m.season_id=sid and v.code=v_code and m.effective_from_matchday_number<=d.number
      and coalesce(m.effective_to_matchday_number,d.number)>=d.number;
    if n>(c.division_sizes->>v_code)::integer then perform public.admin_setup_fail('invalid_roster'); end if;
    expected=expected+n*(n-1)/2;
  end loop;
  if (select count(*) from public.matches where matchday_id=did)<>expected or exists (
    select 1 from public.matches x where x.matchday_id=did and (x.status not in ('scheduled','completed')
    or (x.winner_id is null)<>(x.status='scheduled') or not exists (
      select 1 from public.participant_memberships_at(sid,d.number) a join public.participant_memberships_at(sid,d.number) b on a.division_id=b.division_id
      where a.season_player_id=x.player_a_id and b.season_player_id=x.player_b_id and a.division_id=x.division_id
      and a.effective_from_matchday_number<=d.number and coalesce(a.effective_to_matchday_number,d.number)>=d.number
      and b.effective_from_matchday_number<=d.number and coalesce(b.effective_to_matchday_number,d.number)>=d.number))) then
    perform public.admin_setup_fail('invalid_results'); end if;
  if complete and exists(select 1 from public.matches where matchday_id=did and winner_id is null) then
    perform public.admin_setup_fail('results_incomplete'); end if;
end $$;

create or replace function public.matchday_context(op text,r jsonb) returns jsonb
language plpgsql set search_path=pg_catalog,public as $$
declare sid uuid=(r->>'season_id')::uuid; did uuid=(r->>'resource_id')::uuid;
  d public.matchdays; c public.season_config_versions; inputs jsonb; players jsonb; matches jsonb; result jsonb;
begin
  select * into d from public.matchdays where id=did;
  select * into c from public.season_config_versions where id=d.season_config_version_id;
  if (c.rules_json->>'last_b_gets_steal')::boolean and exists (
    select 1 from public.participant_memberships_at(sid,d.number) m join public.divisions v on v.id=m.division_id where v.code='B'
  ) and not exists (
    select 1 from public.shop_items where code='robar_pokemon' and acquisition_mode='purchasable'
  ) then perform public.admin_setup_fail('reward_item_unavailable'); end if;
  if op='correct' then
    select snapshot->'inputs' into inputs from public.matchday_snapshots where matchday_id=did;
  else
    if exists(select 1 from public.season_players p where p.season_id=sid and (p.status='active' or d.number<p.status_effective_matchday_number) and p.current_save_file_id is not null
      and not exists(select 1 from public.pokemon_identity_revisions i where i.save_file_id=p.current_save_file_id)) then
      perform public.admin_setup_fail('ranking_inputs_unavailable'); end if;
    select jsonb_agg(jsonb_build_object('id',p.id,'trainer_id',p.trainer_id,'ranking_key',t.slug,'division',v.code,
      'dead_count',(select count(*) from public.pokemon_observations o where o.save_file_id=p.current_save_file_id and o.source='box' and o.box_number=8)
        +greatest((select count(*) from public.redemptions e where e.season_id=sid and e.trainer_id=p.trainer_id and e.effect_code='revive' and e.status='applied'),
          (select count(*) from public.purchases u join public.shop_items i on i.id=u.shop_item_id where u.season_player_id=p.id and u.status='used' and i.code='revivir_pokemon'))
        +2*st.revived_after_wipe,
      'points_reduction',coalesce((select sum(greatest(amount,0)) from public.penalties pe where pe.season_id=sid and pe.trainer_id=p.trainer_id
        and pe.penalty_type='points_reduction' and (pe.matchday_id is null or pe.matchday_id=did)
        and (pe.trial_case_id is null or exists(select 1 from public.trial_cases tc where tc.id=pe.trial_case_id and tc.status='resolved'
          and tc.accused_trainer_id=p.trainer_id and (tc.season_id is null or tc.season_id=sid)))),0),
      'coins_reduction',coalesce((select sum(greatest(amount,0)) from public.penalties pe where pe.season_id=sid and pe.trainer_id=p.trainer_id
        and pe.penalty_type='coins_reduction' and (pe.matchday_id is null or pe.matchday_id=did)
        and (pe.trial_case_id is null or exists(select 1 from public.trial_cases tc where tc.id=pe.trial_case_id and tc.status='resolved'
          and tc.accused_trainer_id=p.trainer_id and (tc.season_id is null or tc.season_id=sid)))) ,0)) order by p.id) into players
      from public.season_players p join public.trainers t on t.id=p.trainer_id
      join public.season_player_stats st on st.season_player_id=p.id
      join public.participant_memberships_at(sid,d.number) m on m.season_player_id=p.id and m.effective_from_matchday_number<=d.number
        and coalesce(m.effective_to_matchday_number,d.number)>=d.number
      join public.divisions v on v.id=m.division_id where p.season_id=sid;
    select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'player_a_id',x.player_a_id,'player_b_id',x.player_b_id,
      'winner_id',x.winner_id,'division',v.code) order by x.id),'[]'::jsonb) into matches
      from public.matches x join public.divisions v on v.id=x.division_id where x.matchday_id=did;
    inputs=jsonb_build_object('season_id',sid,'day_id',did,'number',d.number,'results_revision',d.results_revision,
      'config',jsonb_build_object('id',c.id,'name',c.name,'effective_from_matchday',c.effective_from_matchday,
        'total_matchdays',c.total_matchdays,'division_sizes',c.division_sizes,'promotion_relegation_count',c.promotion_relegation_count,
        'scoring_json',c.scoring_json,'coin_rewards_json',c.coin_rewards_json,'rules_json',c.rules_json),
      'players',coalesce(players,'[]'::jsonb),'matches',matches);
  end if;
  result=jsonb_build_object('inputs',inputs,'external_facts',public.matchday_external_facts(sid),
    'snapshot_revision',coalesce((select revision from public.matchday_snapshots where matchday_id=did),0),
    'next_config',(select to_jsonb(x) from public.season_config_versions x where x.season_id=sid and x.effective_from_matchday<=d.number+1
      order by x.effective_from_matchday desc limit 1),
    'existing_next_promotions',exists(select 1 from public.shop_promotions p join public.matchdays md on md.id=p.matchday_id
      where p.season_id=sid and md.number=d.number+1),
    'catalog',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'code',i.code,'name',i.name,'category',i.category,'base_price',i.base_price,'enabled',i.enabled) order by i.id),'[]'::jsonb)
      from public.shop_items i where i.acquisition_mode='purchasable'),
    'purchase_history',(select coalesce(jsonb_agg(jsonb_build_object('name',i.name,'number',coalesce(md.number,0),'quantity',p.quantity) order by p.id),'[]'::jsonb)
      from public.purchases p join public.shop_items i on i.id=p.shop_item_id left join public.matchdays md
      on md.id=coalesce((p.metadata#>>'{normal_purchase,matchday_id}')::uuid,(p.metadata#>>'{promotional_purchase,matchday_id}')::uuid,p.origin_matchday_id)
      where p.season_id=sid and p.status not in ('cancelled','refunded')),
    'promotion_history',(select coalesce(jsonb_agg(jsonb_build_object('item',i.name,'jornada',md.number) order by p.id),'[]'::jsonb)
      from public.shop_promotions p join public.shop_items i on i.id=p.shop_item_id join public.matchdays md on md.id=p.matchday_id where p.season_id=sid));
  return result;
end $$;

create or replace function public.matchday_commit_close(op text,r jsonb,ctx jsonb,plan jsonb) returns void
language plpgsql set search_path=pg_catalog,public as $$
declare sid uuid=(r->>'season_id')::uuid; did uuid=(r->>'resource_id')::uuid; actor uuid=(r->>'actor_trainer_id')::uuid;
  d public.matchdays; cfg public.season_config_versions; nxtcfg public.season_config_versions;
  old public.matchday_snapshots; v_snapshot jsonb; rev integer; final boolean; nextid uuid; divisionid uuid;
  pid uuid; tid uuid; gift uuid; giftplayer uuid; oldgift public.purchases; row jsonb; divcode text;
  v_amount integer; prior integer; stamp timestamptz=clock_timestamp();
begin
  select * into d from public.matchdays where id=did;
  select * into cfg from public.season_config_versions where id=d.season_config_version_id;
  select * into old from public.matchday_snapshots where matchday_id=did;
  rev=coalesce(old.revision,0)+1; final=d.number=cfg.total_matchdays;
  if op='correct' then
    perform public.matchday_results(did,r->'body'->'results',true);
    perform public.matchday_validate(sid,did,true);
  end if;
  if jsonb_typeof(plan->'standings') is distinct from 'array' or jsonb_array_length(plan->'standings')<>
    (select count(*) from public.participant_memberships_at(sid,d.number))
    or (select count(distinct value->>'trainer_id') from jsonb_array_elements(plan->'standings'))<>jsonb_array_length(plan->'standings') then
    perform public.admin_setup_fail('invalid_results'); end if;
  for row in select value from jsonb_array_elements(plan->'standings') loop
    if not exists(select 1 from public.season_players where id=(row->>'trainer_id')::uuid and season_id=sid
      and (status='active' or d.number<status_effective_matchday_number))
      or (row->>'coins_awarded')::integer is distinct from (cfg.coin_rewards_json->>(row->>'position'))::integer
      or (row->>'points_awarded')::integer is distinct from (cfg.scoring_json->>(row->>'position'))::integer then
      perform public.admin_setup_fail('invalid_results'); end if;
  end loop;
  giftplayer=(plan->>'last_b_player_id')::uuid;
  if (cfg.rules_json->>'last_b_gets_steal')::boolean and exists (
    select 1 from public.participant_memberships_at(sid,d.number) m join public.divisions v on v.id=m.division_id where v.code='B'
  ) then
    select id into gift from public.shop_items where code='robar_pokemon' and acquisition_mode='purchasable' for share;
    if gift is null or giftplayer is null then perform public.admin_setup_fail('reward_item_unavailable'); end if;
  elsif giftplayer is not null then perform public.admin_setup_fail('invalid_results'); end if;
  v_snapshot=jsonb_build_object('schema_version',2,'revision',rev,'closed_at',stamp,'inputs',
    jsonb_set(ctx->'inputs','{matches}',plan->'matches'),'standings',plan->'standings',
    'new_divisions',plan->'new_divisions','last_b_player_id',giftplayer,'external_facts',ctx->'external_facts',
    'final',final,'reason',case when op='correct' then r->'body'->>'reason' else 'close' end);
  insert into public.matchday_snapshot_revisions(season_id,matchday_id,revision,snapshot,reason,created_by_trainer_id)
    values(sid,did,rev,v_snapshot,v_snapshot->>'reason',actor);
  if old.id is null then
    insert into public.matchday_snapshots(season_id,matchday_id,config_version_id,revision,snapshot_schema_version,closed_at,snapshot,created_by_trainer_id)
      values(sid,did,cfg.id,rev,2,stamp,v_snapshot,actor);
  else
    update public.matchday_snapshots set revision=rev,snapshot=v_snapshot,closed_at=stamp,created_by_trainer_id=actor where id=old.id;
  end if;
  for row in select value from jsonb_array_elements(plan->'standings') loop
    pid=(row->>'trainer_id')::uuid;
    select trainer_id into tid from public.season_players where id=pid;
    prior=0;
    if old.id is not null then select (x->>'coins_awarded')::integer into prior from jsonb_array_elements(old.snapshot->'standings') x where x->>'trainer_id'=pid::text; end if;
    v_amount=(row->>'coins_awarded')::integer-coalesce(prior,0);
    if v_amount<0 and (select coalesce(sum(amount),0) from public.coin_transactions where season_player_id=pid)+v_amount<0 then
      perform public.admin_setup_fail('correction_window_closed'); end if;
    if v_amount<>0 then
      insert into public.coin_transactions(season_id,trainer_id,season_player_id,amount,transaction_type,reference_type,reference_id,
        reward_matchday_id,reward_revision,created_by_trainer_id,metadata)
        values(sid,tid,pid,v_amount,case when op='close' then 'matchday_reward' else 'compensation' end,
          'matchday_snapshot_revision',(select id from public.matchday_snapshot_revisions where matchday_id=did and revision=rev),
          did,rev,actor,jsonb_build_object('reason',v_snapshot->>'reason','previous_revision',rev-1));
    end if;
  end loop;
  select * into oldgift from public.purchases where origin_matchday_id=did and status='pending' order by origin_snapshot_revision desc limit 1 for update;
  if oldgift.id is not null and oldgift.season_player_id is distinct from giftplayer then
    update public.purchases set status='cancelled',metadata=metadata||jsonb_build_object('cancelled_by_revision',rev,'reason',v_snapshot->>'reason') where id=oldgift.id;
  end if;
  if giftplayer is not null and (oldgift.id is null or oldgift.season_player_id<>giftplayer) then
    select trainer_id into tid from public.season_players where id=giftplayer;
    insert into public.purchases(season_id,trainer_id,season_player_id,shop_item_id,quantity,unit_price,status,
      acquisition_type,origin_matchday_id,origin_snapshot_revision)
      values(sid,tid,giftplayer,gift,1,0,'pending','reward',did,rev);
  end if;
  if not final then
    select * into nxtcfg from public.season_config_versions where season_id=sid and effective_from_matchday<=d.number+1
      order by effective_from_matchday desc limit 1;
    if nxtcfg.total_matchdays<d.number+1 or nxtcfg.division_sizes<>cfg.division_sizes then
      perform public.admin_setup_fail('config_mismatch'); end if;
    select id into nextid from public.matchdays where season_id=sid and number=d.number+1;
    if op='close' and nextid is not null then perform public.admin_setup_fail('dependent_data_exists'); end if;
    if op='correct' then
      delete from public.matchday_movements where matchday_id=did;
      delete from public.matches where matchday_id=nextid;
      delete from public.division_memberships where source_matchday_id=did;
    end if;
    update public.division_memberships set effective_to_matchday_number=d.number where season_id=sid
      and effective_from_matchday_number<=d.number and coalesce(effective_to_matchday_number,d.number)>=d.number
      and (eligibility_ends_before_matchday_number is null or d.number<eligibility_ends_before_matchday_number);
    foreach divcode in array array['A','B'] loop
      select id into divisionid from public.divisions where season_id=sid and code=divcode;
      for pid in select value::uuid from jsonb_array_elements_text(plan->'new_divisions'->divcode) loop
        insert into public.matchday_movements(season_id,matchday_id,season_player_id,from_division_id,to_division_id,movement_type,metadata)
          select sid,did,pid,m.division_id,divisionid,case when m.division_id=divisionid then 'stay' when divcode='A' then 'promotion' else 'relegation' end,
            jsonb_build_object('snapshot_revision',rev) from public.division_memberships m where m.season_player_id=pid
            and m.effective_from_matchday_number<=d.number and m.effective_to_matchday_number=d.number;
        insert into public.division_memberships(season_id,season_player_id,division_id,effective_from_matchday_number,source_matchday_id,reason)
          select sid,pid,divisionid,d.number+1,did,case when movement_type='stay' then 'initial' else movement_type end
            from public.matchday_movements where matchday_id=did and season_player_id=pid;
      end loop;
    end loop;
    if nextid is null then
      insert into public.matchdays(season_id,number,season_config_version_id) values(sid,d.number+1,nxtcfg.id) returning id into nextid;
    end if;
    insert into public.matches(season_id,matchday_id,division_id,player_a_id,player_b_id)
      select sid,nextid,a.division_id,a.season_player_id,b.season_player_id from public.division_memberships a
      join public.division_memberships b on a.division_id=b.division_id and a.season_player_id<b.season_player_id
      where a.season_id=sid and a.effective_from_matchday_number=d.number+1 and b.effective_from_matchday_number=d.number+1;
    perform public.matchday_validate(sid,nextid,false);
    if op='close' then
      for row in select value from jsonb_array_elements(plan->'promotions') loop
        insert into public.shop_promotions(season_id,matchday_id,shop_item_id,promotion_type,status,base_price,effective_price,stock_total,
          announced_at,activates_at,dedupe_key,metadata)
          values(sid,nextid,(row->>'shop_item_id')::uuid,row->>'promotion_type','pending',(row->>'base_price')::integer,
            (row->>'effective_price')::integer,(row->>'stock_total')::integer,stamp,stamp+interval '24 hours',
            'matchday:'||did::text||':'||(row->>'shop_item_id'),jsonb_build_object('source_matchday_id',did));
      end loop;
    end if;
    update public.seasons set current_matchday_id=nextid where id=sid;
  end if;
  if op='close' then
    update public.shop_promotions set status='ended',ends_at=stamp where season_id=sid and status in ('pending','active','exhausted')
      and matchday_id in (select id from public.matchdays where season_id=sid and number<=d.number);
  end if;
  update public.matchdays set status='closed',closed_at=coalesce(closed_at,stamp),revision=revision+1,results_revision=results_revision+1 where id=did;
end $$;

create or replace function public.api_admin_get_setup(p_request jsonb) returns jsonb
language plpgsql set search_path = pg_catalog, public as $$
declare sid uuid=(p_request->>'season_id')::uuid; result jsonb;
begin
  perform public.admin_setup_principal((p_request->>'actor_trainer_id')::uuid);
  -- SHARE holds a coherent multi-query read against every admin mutation.
  perform 1 from public.seasons where id=sid for share;
  if not found then perform public.admin_setup_fail('season_not_found',404); end if;
  select jsonb_build_object('season',jsonb_build_object('id',s.id,'name',s.name,'status',s.status,'started_at',s.started_at),
    'setup_revision',coalesce(a.setup_revision,0),'roster_revision',coalesce(a.roster_revision,0),'config_revision',coalesce(a.config_revision,0),
    'current_matchday_id',s.current_matchday_id,'readiness',public.admin_setup_readiness(sid),
    'participants',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'trainer_id',p.trainer_id,'display_name',t.display_name,
      'status',p.status,'status_effective_matchday_number',p.status_effective_matchday_number,'seed_order',p.seed_order,'stats_ready',st.season_player_id is not null) order by p.id),'[]'::jsonb)
      from public.season_players p join public.trainers t on t.id=p.trainer_id
      left join public.season_player_stats st on st.season_player_id=p.id where p.season_id=sid),
    'config_versions',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'version_number',c.version_number,
      'effective_from_matchday',c.effective_from_matchday,'total_matchdays',c.total_matchdays,'division_sizes',c.division_sizes,
      'movement_count',c.promotion_relegation_count,'scoring',c.scoring_json,'coin_rewards',c.coin_rewards_json,'rules',c.rules_json,
      'roster_revision',c.roster_revision,'used',public.admin_setup_config_used(c.id),
      'is_current',coalesce(c.id=(select x.id from public.season_config_versions x where x.season_id=sid
        and x.effective_from_matchday<=coalesce((select number from public.matchdays where id=s.current_matchday_id),1)
        order by x.effective_from_matchday desc limit 1),false)) order by c.effective_from_matchday),'[]'::jsonb)
      from public.season_config_versions c where c.season_id=sid),
    'divisions',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'code',d.code,'tier_order',d.tier_order) order by d.tier_order),'[]'::jsonb) from public.divisions d where d.season_id=sid),
    'memberships',(select coalesce(jsonb_agg(jsonb_build_object('season_player_id',m.season_player_id,'division_id',m.division_id,
      'effective_from_matchday',m.effective_from_matchday_number,'effective_to_matchday',m.effective_to_matchday_number,'reason',m.reason,'eligibility_ends_before_matchday_number',m.eligibility_ends_before_matchday_number) order by m.season_player_id),'[]'::jsonb) from public.division_memberships m where m.season_id=sid),
    'first_matchday',(select jsonb_build_object('id',d.id,'number',d.number,'status',d.status,'config_version_id',d.season_config_version_id,
      'match_count',(select count(*) from public.matches where matchday_id=d.id)) from public.matchdays d where d.season_id=sid and number=1)) into result
    from public.seasons s left join public.season_admin_state a on a.season_id=s.id where s.id=sid;
  return result;
end $$;

do $$ declare f regprocedure; begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname in ('participant_memberships_at','participant_status_immutable','api_admin_participant_status') loop
    execute format('revoke all on function %s from public,anon,authenticated',f);
    execute format('grant execute on function %s to service_role',f);
  end loop;
end $$;
notify pgrst,'reload schema';
commit;
-- ============================================================================
-- END 028_participant_status_admin.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 029_season_finalization_archive_hall.sql
-- ============================================================================
-- Phase 8J: explicit completion, frozen relational provenance, non-destructive discard.
begin;

alter table public.season_archive_snapshots
  add column source_snapshot_revision_id uuid references public.matchday_snapshot_revisions(id),
  add column checksum text check (checksum ~ '^[0-9a-f]{64}$'),
  add column label text check (length(btrim(label)) between 1 and 120),
  add constraint archive_provenance_complete check (
    (source_snapshot_revision_id is null and checksum is null and label is null) or
    (source_snapshot_revision_id is not null and checksum is not null and label is not null));
alter table public.hall_of_fame_entries
  add column archive_snapshot_id uuid references public.season_archive_snapshots(id),
  add column source_snapshot_revision_id uuid references public.matchday_snapshot_revisions(id),
  add column source_team_lock_id uuid references public.team_locks(id),
  add constraint hall_archive_provenance check (
    (archive_snapshot_id is null and source_snapshot_revision_id is null and source_team_lock_id is null) or
    (competition_type='league' and archive_snapshot_id is not null and source_snapshot_revision_id is not null));

revoke insert,update,delete on public.season_archive_snapshots,public.hall_of_fame_entries from public,anon,authenticated;
do $$ declare t text; c text; begin
  foreach t in array array['season_archive_snapshots','hall_of_fame_entries'] loop
    select string_agg(quote_ident(attname),',') into c from pg_attribute
      where attrelid=('public.'||t)::regclass and attnum>0 and not attisdropped;
    execute format('revoke insert (%s),update (%s) on public.%I from public,anon,authenticated',c,c,t);
  end loop;
end $$;

create function public.lifecycle_artifact_immutable() returns trigger
language plpgsql security invoker set search_path=pg_catalog,public as $$
begin
  if new is distinct from old then perform public.admin_setup_fail('historical_artifact_immutable'); end if;
  return new;
end $$;
create trigger archive_immutable before update on public.season_archive_snapshots
  for each row execute function public.lifecycle_artifact_immutable();
create trigger hall_immutable before update on public.hall_of_fame_entries
  for each row execute function public.lifecycle_artifact_immutable();

-- Re-project rather than copy arbitrary JSON, including nested move metadata.
create function public.lifecycle_public_team(team jsonb) returns jsonb
language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare mon jsonb; safe jsonb; result jsonb='[]'; k text;
begin
  if jsonb_typeof(team) is distinct from 'array' then return '[]'; end if;
  if jsonb_array_length(team)<>6 then return '[]'; end if;
  for mon in select value from jsonb_array_elements(team) loop
    if jsonb_typeof(mon->'species') is distinct from 'string' or length(btrim(mon->>'species'))=0 then return '[]'; end if;
    safe='{}';
    foreach k in array array['species','nickname','gender','item','sprite_url','form_name'] loop
      if jsonb_typeof(mon->k)='string' then safe=safe||jsonb_build_object(k,mon->k); end if;
    end loop;
    foreach k in array array['level','form_index'] loop
      if jsonb_typeof(mon->k)='number' and mon->>k ~ '^[0-9]+$' then safe=safe||jsonb_build_object(k,mon->k); end if;
    end loop;
    if jsonb_typeof(mon->'is_shiny')='boolean' then safe=safe||jsonb_build_object('is_shiny',mon->'is_shiny'); end if;
    if jsonb_typeof(mon->'types')='array' then
      safe=safe||jsonb_build_object('types',(select coalesce(jsonb_agg(value order by ord),'[]') from
        jsonb_array_elements(mon->'types') with ordinality a(value,ord) where ord<=2 and jsonb_typeof(value)='string'));
    end if;
    if jsonb_typeof(mon->'moves')='array' then
      safe=safe||jsonb_build_object('moves',(select coalesce(jsonb_agg(jsonb_build_object('name',value->>'name') order by ord),'[]')
        from jsonb_array_elements(mon->'moves') with ordinality a(value,ord)
        where ord<=4 and jsonb_typeof(value->'name')='string'));
    end if;
    result=result||jsonb_build_array(safe);
  end loop;
  return result;
end $$;

create function public.lifecycle_standings(sid uuid, rows_json jsonb) returns jsonb
language sql stable security invoker set search_path=pg_catalog,public as $$
  select coalesce(jsonb_agg(jsonb_build_object('season_player_id',p.id,'trainer_id',p.trainer_id,
    'position',(r->>'position')::integer,'division',r->>'division_id',
    'division_position',(r->>'division_position')::integer,'score',(r->>'score')::numeric,
    'points_awarded',(r->>'points_awarded')::integer,'coins_awarded',(r->>'coins_awarded')::integer)
    order by (r->>'position')::integer),'[]')
  from jsonb_array_elements(rows_json) r join public.season_players p on p.id=(r->>'trainer_id')::uuid and p.season_id=sid
$$;

create function public.lifecycle_final_source(sid uuid) returns public.matchday_snapshot_revisions
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare finalday public.matchdays; cfg public.season_config_versions; d public.matchdays;
  snap public.matchday_snapshots; history public.matchday_snapshot_revisions; result public.matchday_snapshot_revisions;
  row jsonb; n integer;
begin
  select md.* into finalday from public.matchdays md join public.seasons s on s.current_matchday_id=md.id
    where s.id=sid and md.season_id=sid;
  select * into cfg from public.season_config_versions where id=finalday.season_config_version_id;
  if finalday.id is null or finalday.status<>'closed' or finalday.number is distinct from cfg.total_matchdays
    or cfg.division_sizes is null or exists(select 1 from public.matchdays where season_id=sid and status<>'closed')
    or exists(select 1 from public.season_config_versions where season_id=sid and effective_from_matchday>finalday.number)
    or (select count(*) from public.matchdays where season_id=sid)<>finalday.number
    or (select min(number) from public.matchdays where season_id=sid)<>1
    or (select max(number) from public.matchdays where season_id=sid)<>finalday.number then
    perform public.admin_setup_fail('competition_incomplete'); end if;
  for d in select * from public.matchdays where season_id=sid order by number for update loop
    perform 1 from public.matches where matchday_id=d.id order by id for update;
    perform public.matchday_validate(sid,d.id,true);
    select * into snap from public.matchday_snapshots where matchday_id=d.id for share;
    select * into history from public.matchday_snapshot_revisions where matchday_id=d.id and revision=snap.revision for share;
    if snap.id is null or history.id is null or snap.snapshot_schema_version<>2 or snap.config_version_id<>d.season_config_version_id
      or history.snapshot is distinct from snap.snapshot or history.season_id<>sid
      or snap.revision<>(select max(revision) from public.matchday_snapshot_revisions where matchday_id=d.id)
      or (history.snapshot->>'final')::boolean is distinct from (d.id=finalday.id)
      or history.snapshot#>>'{inputs,season_id}' is distinct from sid::text
      or history.snapshot#>>'{inputs,day_id}' is distinct from d.id::text
      or history.snapshot#>>'{inputs,config,id}' is distinct from d.season_config_version_id::text
      or jsonb_typeof(history.snapshot->'standings') is distinct from 'array' then
      perform public.admin_setup_fail('historical_source_invalid'); end if;
    if (select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'player_a_id',m.player_a_id,'player_b_id',m.player_b_id,
        'winner_id',m.winner_id,'division',v.code) order by m.id),'[]') from public.matches m join public.divisions v on v.id=m.division_id
        where m.matchday_id=d.id) is distinct from
      (select coalesce(jsonb_agg(value order by (value->>'id')::uuid),'[]') from jsonb_array_elements(history.snapshot#>'{inputs,matches}')) then
      perform public.admin_setup_fail('historical_source_invalid'); end if;
    n=jsonb_array_length(history.snapshot->'standings');
    if n<>(select count(*) from public.participant_memberships_at(sid,d.number))
      or n<>(select count(distinct r->>'trainer_id') from jsonb_array_elements(history.snapshot->'standings') r)
      or n<>(select count(distinct (r->>'position')::integer) from jsonb_array_elements(history.snapshot->'standings') r
        where (r->>'position')::integer between 1 and n) then perform public.admin_setup_fail('historical_source_invalid'); end if;
    for row in select value from jsonb_array_elements(history.snapshot->'standings') loop
      if not exists(select 1 from public.participant_memberships_at(sid,d.number) where season_player_id=(row->>'trainer_id')::uuid)
        or (row->>'coins_awarded')::integer is distinct from (select coalesce(sum(amount),0) from public.coin_transactions
          where reward_matchday_id=d.id and season_player_id=(row->>'trainer_id')::uuid) then
        perform public.admin_setup_fail('historical_source_invalid'); end if;
    end loop;
    if history.snapshot->>'last_b_player_id' is not null and not exists (
      select 1 from public.purchases p join public.shop_items i on i.id=p.shop_item_id
      where p.origin_matchday_id=d.id and p.season_player_id=(history.snapshot->>'last_b_player_id')::uuid
        and p.acquisition_type='reward' and p.unit_price=0 and p.status not in ('cancelled','refunded') and i.code='robar_pokemon'
    ) then perform public.admin_setup_fail('historical_source_invalid'); end if;
    if d.id=finalday.id then result=history; end if;
  end loop;
  return result;
end $$;

create function public.lifecycle_draft_safe(sid uuid) returns boolean
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare t text; occupied boolean;
begin
  -- Pure draft roster/config/divisions are retained. Prepared rounds are ambiguous
  -- and require a separate exceptional contract, not silent deletion.
  foreach t in array array['matchdays','matches','matchday_snapshots','matchday_snapshot_revisions','matchday_movements',
    'team_locks','save_files','parsed_saves','pokemon_entities','pokemon_observations','pokemon_identity_revisions',
    'pokemon_entity_flags','pokemon_flags','trainer_flags','robbery_cycles','purchases','redemptions','coin_transactions',
    'shop_promotions','cups','trial_cases','penalties','hall_of_fame_entries','season_archive_snapshots'] loop
    -- parsed_saves is owned through save_files; the parent check suffices.
    if t='parsed_saves' then continue; end if;
    execute format('select exists(select 1 from public.%I where season_id=$1)',t) into occupied using sid;
    if occupied then return false; end if;
  end loop;
  return not exists(select 1 from public.season_players where season_id=sid and
      (status<>'active' or current_save_file_id is not null))
    and not exists(select 1 from public.season_player_stats where season_id=sid and
      (badges_count<>0 or revived_after_wipe<>0));
end $$;

create function public.api_admin_season_lifecycle(p_request jsonb) returns jsonb
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare r jsonb=p_request; b jsonb=r->'body'; op text=r->>'operation'; sid uuid=(r->>'season_id')::uuid;
  actor uuid=(r->>'actor_trainer_id')::uuid; s public.seasons; source public.matchday_snapshot_revisions;
  cached jsonb; result jsonb; artifact jsonb; roster jsonb; rounds jsonb; team jsonb='[]'; standings jsonb;
  champion uuid; finalist uuid; lockid uuid; lockrow record; stamp timestamptz; label text;
  aid uuid; hid uuid; oid uuid=gen_random_uuid(); eid uuid=gen_random_uuid(); destination text;
begin
  if op not in ('finish','archive','discard') or op is null or sid is null
    or jsonb_typeof(b) is distinct from 'object'
    or jsonb_typeof(b->'expected_revision') is distinct from 'number'
    or b->>'expected_revision' !~ '^[0-9]+$'
    or (op='finish' and b-'expected_revision'<>'{}')
    or (op='archive' and (b-array['expected_revision','label']<>'{}' or
      (b->'label' is not null and b->'label'<>'null' and (jsonb_typeof(b->'label')<>'string' or length(btrim(b->>'label')) not between 1 and 120))))
    or (op='discard' and (b-array['expected_revision','reason','confirmation']<>'{}' or b->>'confirmation' is distinct from 'DISCARD'
      or jsonb_typeof(b->'reason') is distinct from 'string' or length(btrim(b->>'reason')) not between 1 and 500)) then
    perform public.admin_setup_fail('invalid_request',422); end if;
  cached=public.admin_setup_begin('lifecycle',r); if cached is not null then return cached; end if;
  select * into s from public.seasons where id=sid;
  if op='finish' and s.status<>'active' then perform public.admin_setup_fail('season_not_active'); end if;
  if op='archive' and s.status<>'finished' then perform public.admin_setup_fail('season_not_finished'); end if;
  if op='discard' and (s.status<>'draft' or not public.lifecycle_draft_safe(sid)) then
    perform public.admin_setup_fail('discard_not_allowed'); end if;
  perform public.admin_setup_cas(sid,b);
  if op in ('finish','archive') then source=public.lifecycle_final_source(sid); end if;
  stamp=clock_timestamp();
  destination=case op when 'finish' then 'finished' when 'archive' then 'archived' else 'discarded' end;
  if op='finish' then
    update public.seasons set status='finished',finished_at=stamp where id=sid;
  elsif op='discard' then
    update public.seasons set status='discarded',discarded_at=stamp where id=sid;
  else
    standings=public.lifecycle_standings(sid,source.snapshot->'standings');
    champion=(standings->0->>'trainer_id')::uuid; finalist=(standings->1->>'trainer_id')::uuid;
    -- The existing Hall requires a real champion; an empty final competition
    -- cannot fabricate one. Missing team evidence, unlike champion, is optional.
    if champion is null then perform public.admin_setup_fail('historical_source_invalid'); end if;
    if exists(select 1 from public.season_archive_snapshots where season_id=sid)
      or exists(select 1 from public.hall_of_fame_entries where season_id=sid and competition_type='league') then
      perform public.admin_setup_fail('historical_artifact_exists'); end if;
    for lockrow in select l.* from public.team_locks l join public.matchdays d on d.id=l.matchday_id
      where l.season_id=sid and l.trainer_id=champion and d.season_id=sid and d.status='closed'
        and d.number<=(select number from public.matchdays where id=source.matchday_id)
      order by d.number desc,l.id for share of l loop
      team=public.lifecycle_public_team(lockrow.public_team_snapshot);
      if jsonb_array_length(team)=6 then lockid=lockrow.id; exit; end if;
    end loop;
    label=coalesce(btrim(b->>'label'),s.name); aid=gen_random_uuid(); hid=gen_random_uuid();
    select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'trainer_id',p.trainer_id,'display_name',t.display_name,
      'status',p.status,'status_effective_matchday_number',p.status_effective_matchday_number,'seed_order',p.seed_order)
      order by p.id),'[]') into roster from public.season_players p join public.trainers t on t.id=p.trainer_id where p.season_id=sid;
    select jsonb_agg(jsonb_build_object('id',d.id,'number',d.number,'config_version_id',d.season_config_version_id,
      'snapshot_revision',x.revision,'closed_at',x.closed_at,'standings',public.lifecycle_standings(sid,x.snapshot->'standings'))
      order by d.number) into rounds from public.matchdays d join public.matchday_snapshots x on x.matchday_id=d.id where d.season_id=sid;
    artifact=jsonb_build_object('schema_version',1,'season',jsonb_build_object('id',sid,'name',s.name,'label',label,
      'started_at',s.started_at,'finished_at',s.finished_at,'archived_at',stamp),
      'source_snapshot_revision_id',source.id,'final_matchday_id',source.matchday_id,'roster',roster,'standings',standings,'rounds',rounds,
      'config_versions',(select jsonb_agg(jsonb_build_object('id',c.id,'version',c.version_number,'name',c.name,
        'effective_from_matchday',c.effective_from_matchday,'total_matchdays',c.total_matchdays,'division_sizes',c.division_sizes,
        'movement_count',c.promotion_relegation_count,'scoring',c.scoring_json,'coin_rewards',c.coin_rewards_json,'rules',c.rules_json)
        order by c.version_number) from public.season_config_versions c where c.season_id=sid),
      'movements',(select coalesce(jsonb_agg(jsonb_build_object('matchday_id',m.matchday_id,'season_player_id',m.season_player_id,
        'from_division_id',m.from_division_id,'to_division_id',m.to_division_id,'type',m.movement_type) order by m.id),'[]')
        from public.matchday_movements m where m.season_id=sid),
      'league',jsonb_build_object('champion_trainer_id',champion,'finalist_trainer_id',finalist,'team',team,'source_team_lock_id',lockid),
      'cup_hall_status','pending_cup_api');
    update public.seasons set status='archived',archived_at=stamp where id=sid;
    insert into public.season_archive_snapshots(id,season_id,snapshot_schema_version,snapshot,created_by_trainer_id,
      source_snapshot_revision_id,checksum,label,created_at)
      values(aid,sid,1,artifact,actor,source.id,encode(sha256(convert_to(artifact::text,'UTF8')),'hex'),label,stamp);
    insert into public.hall_of_fame_entries(id,season_id,competition_type,champion_trainer_id,finalist_trainer_id,
      finalized_at,team_snapshot,archive_snapshot_id,source_snapshot_revision_id,source_team_lock_id)
      values(hid,sid,'league',champion,finalist,stamp,team,aid,source.id,lockid);
  end if;
  update public.season_admin_state set setup_revision=setup_revision+1 where season_id=sid;
  insert into public.activity_events(id,season_id,type,actor_trainer_id,visibility,dedupe_key,payload)
    values(eid,sid,'SEASON_'||upper(destination),actor,'admin','season-lifecycle:'||oid::text,
      jsonb_build_object('operation_id',oid,'before',s.status,'after',destination,'reason',b->>'reason',
        'final_matchday_id',s.current_matchday_id,'archive_id',aid,'hall_id',hid));
  select jsonb_build_object('operation_id',oid,'event_id',eid,'season_id',sid,'operation',op,'state',destination,
    'actor_trainer_id',actor,'changed_at',stamp,'setup_revision',setup_revision,'current_matchday_id',s.current_matchday_id,
    'archive_id',aid,'hall_id',hid,'replayed',false) into result from public.season_admin_state where season_id=sid;
  insert into public.admin_operation_receipts(id,actor_trainer_id,season_id,operation_scope,idempotency_key,request_hash,response_json)
    values(oid,actor,sid,public.admin_setup_scope('lifecycle',r),r->>'idempotency_key',encode(sha256(convert_to(r::text,'UTF8')),'hex'),result);
  return result;
end $$;

-- Keep existing view projections/options/grants; add the missing parent filter.
-- Direct table SELECT also needs a restrictive policy: views are not the only API.
do $$ declare v record; t record; definition text; begin
  for v in select c.table_name from information_schema.columns c join pg_views p on p.schemaname=c.table_schema and p.viewname=c.table_name
    where c.table_schema='public' and c.column_name='season_id' and c.table_name like 'public_%' order by c.table_name loop
    select pg_get_viewdef(('public.'||v.table_name)::regclass,true) into definition;
    execute format('create or replace view public.%I with (security_invoker=false,security_barrier=true) as
      select v.* from (%s) v where v.season_id is null or exists(select 1 from public.seasons s where s.id=v.season_id and s.status<>''discarded'')',
      v.table_name,rtrim(definition,'; '||chr(10)));
  end loop;
  for v in select unnest(array['public_cup_participants','public_cup_matches','public_cup_standings']) as name loop
    select pg_get_viewdef(('public.'||v.name)::regclass,true) into definition;
    execute format('create or replace view public.%I with (security_invoker=false,security_barrier=true) as
      select v.* from (%s) v where exists(select 1 from public.cups c left join public.seasons s on s.id=c.season_id
      where c.id=v.cup_id and c.status<>''discarded'' and (c.season_id is null or s.status<>''discarded''))',v.name,rtrim(definition,'; '||chr(10)));
  end loop;
  create policy lifecycle_discarded_visibility on public.seasons as restrictive for select to authenticated
    using (status<>'discarded' or public.is_current_user_admin());
  for t in select c.table_name from information_schema.columns c join pg_tables p on p.schemaname=c.table_schema and p.tablename=c.table_name
    where c.table_schema='public' and c.column_name='season_id'
      and c.table_name in ('season_players','season_player_stats','season_config_versions','divisions','division_memberships')
      order by c.table_name loop
    execute format('create policy lifecycle_discarded_visibility on public.%I as restrictive for select to authenticated
      using (public.is_current_user_admin() or season_id is null or exists(select 1 from public.public_seasons s where s.id=season_id))',t.table_name);
  end loop;
  -- Owner-only redemption/history reads retain the 024/025 contract, including
  -- pre-029 imported discarded seasons. Public activity must still be hidden.
  create policy lifecycle_discarded_visibility on public.activity_events as restrictive for select to authenticated
    using (visibility<>'public' or public.is_current_user_admin() or season_id is null
      or exists(select 1 from public.public_seasons s where s.id=season_id));
  for t in select unnest(array['cup_participants','cup_matches','cup_standings']) as name loop
    execute format('create policy lifecycle_discarded_visibility on public.%I as restrictive for select to authenticated
      using (public.is_current_user_admin() or exists(select 1 from public.public_cups c where c.id=cup_id))',t.name);
  end loop;
end $$;

do $$ declare f regprocedure; begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and (p.proname like 'lifecycle_%' or p.proname='api_admin_season_lifecycle') loop
    execute format('revoke all on function %s from public,anon,authenticated',f);
    execute format('grant execute on function %s to service_role',f);
  end loop;
end $$;
notify pgrst,'reload schema';
commit;
-- ============================================================================
